window.KHO_DATA_L5_AMNHAC = [
{"lop":5,"mon":"Âm nhạc","tuan":1,"tiet":1,"bai":"Chủ đề 1: Khúc ca ngày mới — Học hát: Chim sơn ca","yccd":"1. Năng lực âm nhạc (đặc thù)\n- Hát đúng cao độ, trường độ, lời ca bài Chim sơn ca; thể hiện được tính chất vui tươi, trong sáng, rộn ràng.\n- Biết hát rõ lời, lấy hơi đúng chỗ, tư thế hát tự nhiên; bước đầu hát kết hợp vỗ tay theo phách.\n2. Năng lực chung\n- Tự chủ và tự học: Chủ động, tích cực luyện tập; mạnh dạn thể hiện và tự điều chỉnh khi hát chưa đúng.\n- Giao tiếp và hợp tác: Biết phối hợp nhịp nhàng cùng bạn trong hoạt động nhóm; lắng nghe, chia sẻ, nhận xét.\n- Giải quyết vấn đề và sáng tạo: Bước đầu nghĩ ra cách gõ đệm, động tác vận động phù hợp.\n3. Phẩm chất\n- Yêu thiên nhiên, yêu cuộc sống; cảm nhận vẻ đẹp của buổi sáng và tiếng chim.\n- Chăm chỉ, tích cực tham gia các hoạt động ca hát.\n4. Tích hợp\n- Năng lực số 1.1 CB2 (Duyệt, tìm kiếm và lọc dữ liệu, thông tin, nội dung số): HS nghe bản thu mẫu, hát đúng cao độ và biết xin mở lại đúng câu mình còn sai.","dodung":"- GV: Máy tính, ti vi/máy chiếu, loa; bài giảng điện tử có file âm thanh, video, hình ảnh minh hoạ; đàn phím điện tử (organ); nhạc cụ gõ (thanh phách, song loan, trống con, tem-bơ-rin) và nhạc cụ giai điệu (ri-coóc-đơ hoặc kèn phím) nếu có.\n- HS: SGK Âm nhạc 5 (Kết nối tri thức với cuộc sống), vở ghi, đồ dùng học tập; nhạc cụ gõ tự tạo nếu có.","hoatdong":[{"ten":"A. KHỞI ĐỘNG (5 phút)","gv":"Mục tiêu: Tạo tâm thế vui vẻ, kết nối vào bài học.\n- GV cho HS nghe/xem một đoạn tiếng chim hót buổi sáng và hỏi cảm nhận; dẫn dắt vào bài Chim sơn ca.","hs":"- HS lắng nghe, trả lời, ghi tên bài học."},{"ten":"B. KHÁM PHÁ – HÌNH THÀNH KIẾN THỨC (15 phút)","gv":"Mục tiêu: HS hình thành kiến thức, kĩ năng trọng tâm của tiết.\n- GV giới thiệu, hát mẫu bài Chim sơn ca; hỏi cảm nhận ban đầu về giai điệu.\n- GV hướng dẫn đọc lời ca theo tiết tấu, chia bài thành các câu hát.\n- Dạy hát nối tiếp từng câu; nhắc HS hát rõ lời, lấy hơi đầu câu.","hs":"- HS lắng nghe, quan sát, thực hành theo hướng dẫn của GV."},{"ten":"C. LUYỆN TẬP – THỰC HÀNH (10 phút)","gv":"Mục tiêu: HS luyện tập, củng cố kĩ năng vừa học.\n- Cả lớp hát cả bài kết hợp vỗ tay theo phách; luyện theo tổ, nhóm, cá nhân.\n- GV sửa sai về cao độ, tiết tấu, phát âm.","hs":"- HS luyện tập theo tổ, nhóm, cá nhân; tự nhận xét và sửa sai."},{"ten":"D. VẬN DỤNG (5 phút)","gv":"Mục tiêu: HS vận dụng, sáng tạo và liên hệ thực tế.\n- HS hát lại bài cho người thân nghe; chia sẻ điều em thích ở buổi sáng bắt đầu ngày mới.","hs":"- HS vận dụng, biểu diễn/chia sẻ; lắng nghe dặn dò."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 2) GV mở bản thu mẫu bài “Chim sơn ca” từ học liệu điện tử của bộ sách, chỉ cho HS dòng ghi tên tác giả in kèm bản nhạc trong sách; HS nghe trọn bài một lần để nắm giai điệu và chỗ ngân, sau đó nghe từng câu và hát theo, chủ động xin GV mở lại đúng câu mình còn hát chênh.\n- (Miền 3: Sáng tạo nội dung số — Cơ bản, bậc 2) Tập xong, mỗi tổ tự thu âm phần trình bày bài “Chim sơn ca” bằng điện thoại hoặc máy tính của lớp, nghe lại rồi chỉ ra chỗ vào chưa đều, chỗ hát chưa rõ lời để sửa và thu lần thứ hai.\n⚠ (Miền 4: An toàn) Chỉ lấy bản thu từ học liệu của bộ sách hoặc kênh chính thức của nhà xuất bản, không tải nhạc từ trang lạ và không chép nhạc của người khác rồi nhận là của mình; khi giới thiệu bài “Chim sơn ca” phải nêu tên tác giả; bản thu giọng hát của tổ chỉ dùng trong giờ học, muốn gửi cho ai phải hỏi ý kiến cả tổ và GV.","hs":"- HS nghe bản thu mẫu, hát đúng cao độ và biết xin mở lại đúng câu mình còn sai.\n- HS thu âm, nghe lại phần trình bày bài “Chim sơn ca” của tổ và nêu được chỗ đã sửa ở lần thu thứ hai."}]},
{"lop":5,"mon":"Âm nhạc","tuan":2,"tiet":2,"bai":"Chủ đề 1: Khúc ca ngày mới — Lí thuyết âm nhạc: Trọng âm, phách, vạch nhịp, ô nhịp; Ôn tập bài hát Chim sơn ca","yccd":"1. Năng lực âm nhạc (đặc thù)\n- Nhận biết và giải thích được khái niệm trọng âm, phách, vạch nhịp, ô nhịp; biết vỗ tay/gõ thể hiện phách mạnh – phách nhẹ.\n- Hát thuộc lời, đúng giai điệu bài Chim sơn ca; hát kết hợp gõ đệm theo phách.\n2. Năng lực chung\n- Tự chủ và tự học: Chủ động luyện tập, tự điều chỉnh khi gõ phách chưa đúng.\n- Giao tiếp và hợp tác: Phối hợp cùng bạn trong hoạt động nhóm; lắng nghe, nhận xét.\n- Giải quyết vấn đề và sáng tạo: Bước đầu tạo mẫu gõ phách đơn giản.\n3. Phẩm chất\n- Chăm chỉ luyện tập; yêu thích tìm hiểu kiến thức âm nhạc.\n- Trách nhiệm trong hoạt động nhóm.\n4. Tích hợp\n- Năng lực số 1.1 CB2 (Duyệt, tìm kiếm và lọc dữ liệu, thông tin, nội dung số): HS đọc và ghi được kí hiệu về Trọng âm, phách, vạch nhịp, ô nhịp nhờ đối chiếu hình vẽ trên màn hình với âm thanh nghe được.","dodung":"- GV: Máy tính, ti vi/máy chiếu, loa; bài giảng điện tử có sơ đồ trọng âm – phách – vạch nhịp – ô nhịp; đàn phím điện tử; nhạc cụ gõ.\n- HS: SGK Âm nhạc 5 (Kết nối tri thức với cuộc sống), vở ghi, nhạc cụ gõ.","hoatdong":[{"ten":"A. KHỞI ĐỘNG (5 phút)","gv":"Mục tiêu: Tạo tâm thế vui vẻ, kết nối vào bài học.\n- GV cho lớp hát lại bài Chim sơn ca kết hợp vỗ tay để khởi động giọng và ôn phách.","hs":"- HS hát và vỗ tay theo phách."},{"ten":"B. KHÁM PHÁ – HÌNH THÀNH KIẾN THỨC (15 phút)","gv":"Mục tiêu: HS hình thành kiến thức, kĩ năng trọng tâm của tiết.\n- GV dùng sơ đồ minh hoạ giới thiệu trọng âm, phách, vạch nhịp, ô nhịp; làm mẫu vỗ tay phân biệt phách mạnh – phách nhẹ.\n- GV liên hệ vào bài Chim sơn ca để HS nhận ra vạch nhịp, ô nhịp trên bản nhạc.","hs":"- HS quan sát, lắng nghe, thực hành vỗ tay phân biệt phách theo hướng dẫn."},{"ten":"C. LUYỆN TẬP – THỰC HÀNH (10 phút)","gv":"Mục tiêu: HS luyện tập, củng cố kĩ năng vừa học.\n- HS ôn bài hát kết hợp gõ đệm theo phách; luyện theo tổ, nhóm.\n- GV cho HS gõ mẫu tiết tấu có phách mạnh – phách nhẹ; sửa sai.","hs":"- HS luyện tập theo tổ, nhóm, cá nhân; tự nhận xét và sửa sai."},{"ten":"D. VẬN DỤNG (5 phút)","gv":"Mục tiêu: HS vận dụng, sáng tạo và liên hệ thực tế.\n- HS tự nghĩ một mẫu gõ 2 phách (mạnh – nhẹ) để đệm cho câu hát yêu thích.","hs":"- HS sáng tạo mẫu gõ và trình bày; lắng nghe dặn dò."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 2) GV dùng học liệu số về Trọng âm, phách, vạch nhịp, ô nhịp: khuông nhạc hiện trên màn hình, GV kéo nốt lên xuống thì máy phát ngay âm thanh tương ứng, bấm vào hình nốt thì nghe được đúng độ dài của nốt đó — HS thấy được mối liên hệ giữa kí hiệu ghi trên giấy và âm thanh thật, điều mà nhìn hình in tĩnh trong sách không cho thấy.\n- (Miền 5: Giải quyết vấn đề — Cơ bản, bậc 2) HS làm bộ bài tập tương tác có chấm ngay về Trọng âm, phách, vạch nhịp, ô nhịp: đặt nốt vào đúng vị trí trên khuông, chọn hình nốt đúng với tiếng gõ vừa nghe, chia ô nhịp cho đủ phách; sai ở đâu máy báo ngay, HS xem lại phần lí thuyết đúng chỗ đó rồi làm lại.\n⚠ (Miền 4: An toàn) Chỉ mở học liệu và phần mềm GV đã chuẩn bị sẵn trên máy của lớp, không mở trang khác trong giờ; làm hết bài rồi mới xem đáp án, xem để hiểu chứ không chép; ngồi cách màn hình vừa tầm mắt và nghỉ mắt sau mỗi 20 phút nhìn màn hình.","hs":"- HS đọc và ghi được kí hiệu về Trọng âm, phách, vạch nhịp, ô nhịp nhờ đối chiếu hình vẽ trên màn hình với âm thanh nghe được.\n- HS làm bài tập tương tác, tự biết mình còn sai phần nào và ôn lại đúng phần đó."}]},
{"lop":5,"mon":"Âm nhạc","tuan":3,"tiet":3,"bai":"Chủ đề 1: Khúc ca ngày mới — Đọc nhạc: Bài số 1; Ôn tập bài hát Chim sơn ca","yccd":"1. Năng lực âm nhạc (đặc thù)\n- Đọc đúng cao độ, trường độ Bài đọc nhạc số 1; biết đọc kết hợp gõ đệm theo phách.\n- Hát thuộc bài Chim sơn ca, biết hát kết hợp vận động phụ hoạ đơn giản.\n2. Năng lực chung\n- Tự chủ và tự học: Chủ động luyện đọc nhạc, tự sửa khi đọc chưa đúng.\n- Giao tiếp và hợp tác: Phối hợp đọc nhạc theo nhóm; lắng nghe, nhận xét bạn.\n- Giải quyết vấn đề và sáng tạo: Bước đầu ghép đọc nhạc với gõ đệm.\n3. Phẩm chất\n- Chăm chỉ, kiên trì luyện đọc nhạc.\n- Trách nhiệm và hợp tác trong nhóm.\n4. Tích hợp\n- Năng lực số 1.1 CB2 (Duyệt, tìm kiếm và lọc dữ liệu, thông tin, nội dung số): HS đọc đúng cao độ “Bài số 1” nhờ nghe mẫu từ đàn phím.","dodung":"- GV: Máy tính, ti vi/máy chiếu, loa; bài giảng điện tử có Bài đọc nhạc số 1 (khuông nhạc, nốt); đàn phím điện tử; nhạc cụ gõ.\n- HS: SGK Âm nhạc 5 (Kết nối tri thức với cuộc sống), vở ghi, nhạc cụ gõ.","hoatdong":[{"ten":"A. KHỞI ĐỘNG (5 phút)","gv":"Mục tiêu: Tạo tâm thế vui vẻ, kết nối vào bài học.\n- GV cho HS luyện thanh theo mẫu âm ngắn để khởi động giọng và làm quen cao độ.","hs":"- HS luyện thanh theo GV."},{"ten":"B. KHÁM PHÁ – HÌNH THÀNH KIẾN THỨC (15 phút)","gv":"Mục tiêu: HS hình thành kiến thức, kĩ năng trọng tâm của tiết.\n- GV giới thiệu Bài đọc nhạc số 1; hướng dẫn HS nhận biết tên nốt, hình nốt.\n- GV đọc mẫu, hướng dẫn đọc từng câu, đọc kết hợp gõ phách.","hs":"- HS quan sát, đọc theo mẫu, thực hành từng câu."},{"ten":"C. LUYỆN TẬP – THỰC HÀNH (10 phút)","gv":"Mục tiêu: HS luyện tập, củng cố kĩ năng vừa học.\n- HS đọc cả bài kết hợp gõ đệm theo phách; luyện theo tổ, nhóm, cá nhân.\n- Ôn bài hát Chim sơn ca kết hợp vận động; GV sửa sai.","hs":"- HS luyện tập theo tổ, nhóm, cá nhân; tự nhận xét và sửa sai."},{"ten":"D. VẬN DỤNG (5 phút)","gv":"Mục tiêu: HS vận dụng, sáng tạo và liên hệ thực tế.\n- HS đọc nhạc kết hợp gõ đệm biểu diễn theo nhóm; chia sẻ cảm nhận.","hs":"- HS biểu diễn nhóm; lắng nghe dặn dò."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 2) GV dùng đàn phím điện tử hoặc phần mềm đàn phím lấy cao độ chuẩn cho “Bài số 1”: nghe mẫu từng nốt, nghe cả câu ở tốc độ chậm rồi tăng dần; HS chủ động xin nghe lại đúng quãng mình còn đọc chênh thay vì đọc lại cả bài.\n- (Miền 5: Giải quyết vấn đề — Cơ bản, bậc 2) HS luyện “Bài số 1” bằng phần mềm đọc nhạc có chấm ngay: máy phát nốt, HS đọc lại, máy báo đúng hay còn cao hơn, thấp hơn; HS xem kết quả để tự chọn quãng cần luyện thêm và đặt mục tiêu cho lần sau.\n⚠ (Miền 4: An toàn) Chỉ mở phần mềm đàn phím và phần mềm đọc nhạc GV đã chỉ định, không mở trang khác trong giờ thực hành; nếu dùng tai nghe thì để âm lượng vừa và không quá 20 phút liên tục; máy chỉ báo được đúng sai về cao độ, còn đọc có mềm mại hay không thì phải nghe bằng tai mình và nghe GV góp ý.","hs":"- HS đọc đúng cao độ “Bài số 1” nhờ nghe mẫu từ đàn phím.\n- HS tự xác định quãng mình còn đọc chênh và luyện lại đúng quãng đó."}]},
{"lop":5,"mon":"Âm nhạc","tuan":4,"tiet":4,"bai":"Chủ đề 1: Khúc ca ngày mới — Nhạc cụ; Vận dụng – Sáng tạo (tổng kết chủ đề 1)","yccd":"1. Năng lực âm nhạc (đặc thù)\n- Biết sử dụng nhạc cụ gõ (hoặc nhạc cụ giai điệu) thể hiện mẫu tiết tấu đơn giản để đệm cho bài Chim sơn ca.\n- Vận dụng kiến thức trọng âm – phách vào biểu diễn; thể hiện được tính chất vui tươi của chủ đề.\n2. Năng lực chung\n- Tự chủ và tự học: Chủ động luyện tập nhạc cụ.\n- Giao tiếp và hợp tác: Phối hợp nhịp nhàng trong nhóm hoà tấu.\n- Giải quyết vấn đề và sáng tạo: Sáng tạo hình thức biểu diễn tổng hợp hát – gõ đệm – vận động.\n3. Phẩm chất\n- Yêu thích âm nhạc, tự tin biểu diễn.\n- Chăm chỉ, đoàn kết trong hoạt động tập thể.","dodung":"- GV: Máy tính, ti vi/máy chiếu, loa; bài giảng điện tử; đàn phím điện tử; nhạc cụ gõ (thanh phách, song loan, trống con, tem-bơ-rin), nhạc cụ giai điệu (ri-coóc-đơ/kèn phím) nếu có.\n- HS: SGK Âm nhạc 5 (Kết nối tri thức với cuộc sống), vở ghi, nhạc cụ gõ tự tạo nếu có.","hoatdong":[{"ten":"A. KHỞI ĐỘNG (5 phút)","gv":"Mục tiêu: Tạo tâm thế vui vẻ, kết nối vào bài học.\n- GV cho HS chơi trò chơi gõ tiết tấu vọng lại (GV gõ mẫu – HS gõ lặp).","hs":"- HS tham gia trò chơi gõ tiết tấu."},{"ten":"B. KHÁM PHÁ – HÌNH THÀNH KIẾN THỨC (15 phút)","gv":"Mục tiêu: HS hình thành kiến thức, kĩ năng trọng tâm của tiết.\n- GV giới thiệu mẫu tiết tấu đệm cho bài Chim sơn ca; hướng dẫn cách cầm và sử dụng nhạc cụ gõ/giai điệu.\n- GV làm mẫu, hướng dẫn HS thực hiện từng mẫu tiết tấu.","hs":"- HS quan sát, thực hành sử dụng nhạc cụ theo mẫu."},{"ten":"C. LUYỆN TẬP – THỰC HÀNH (10 phút)","gv":"Mục tiêu: HS luyện tập, củng cố kĩ năng vừa học.\n- HS luyện đệm nhạc cụ theo nhóm; ghép hát với gõ đệm.\n- GV sửa tiết tấu, hướng dẫn phối hợp nhịp nhàng.","hs":"- HS luyện tập theo nhóm; tự nhận xét và sửa sai."},{"ten":"D. VẬN DỤNG (5 phút)","gv":"Mục tiêu: HS vận dụng, sáng tạo và liên hệ thực tế.\n- Các nhóm biểu diễn tổng hợp hát – gõ đệm – vận động khép lại chủ đề 1; bình chọn nhóm thể hiện hay.","hs":"- HS biểu diễn nhóm, nhận xét bạn; lắng nghe dặn dò."}]},
{"lop":5,"mon":"Âm nhạc","tuan":5,"tiet":5,"bai":"Chủ đề 2: Giai điệu quê hương — Học hát: Lí đất giồng (Dân ca Nam Bộ)","yccd":"1. Năng lực âm nhạc (đặc thù)\n- Hát đúng cao độ, trường độ, lời ca bài Lí đất giồng; thể hiện được tính chất mượt mà, tình cảm của dân ca Nam Bộ.\n- Biết hát rõ lời, lấy hơi đúng chỗ; bước đầu hát kết hợp gõ đệm theo nhịp.\n2. Năng lực chung\n- Tự chủ và tự học: Chủ động luyện tập, tự điều chỉnh khi hát chưa đúng.\n- Giao tiếp và hợp tác: Phối hợp cùng bạn trong nhóm; lắng nghe, chia sẻ.\n- Giải quyết vấn đề và sáng tạo: Bước đầu nghĩ cách gõ đệm, động tác phù hợp dân ca.\n3. Phẩm chất\n- Yêu quê hương, trân trọng dân ca và di sản âm nhạc dân tộc.\n- Chăm chỉ, tích cực tham gia hoạt động ca hát.\n4. Tích hợp\n- Năng lực số 1.1 CB2 (Duyệt, tìm kiếm và lọc dữ liệu, thông tin, nội dung số): HS nghe bản thu mẫu, hát đúng cao độ và biết xin mở lại đúng câu mình còn sai.","dodung":"- GV: Máy tính, ti vi/máy chiếu, loa; bài giảng điện tử có file hát mẫu, hình ảnh vùng đất Nam Bộ; đàn phím điện tử; nhạc cụ gõ.\n- HS: SGK Âm nhạc 5 (Kết nối tri thức với cuộc sống), vở ghi, nhạc cụ gõ.","hoatdong":[{"ten":"A. KHỞI ĐỘNG (5 phút)","gv":"Mục tiêu: Tạo tâm thế vui vẻ, kết nối vào bài học.\n- GV cho HS xem vài hình ảnh quê hương Nam Bộ (sông nước, đồng ruộng), hỏi cảm nhận; dẫn vào bài Lí đất giồng.","hs":"- HS quan sát, chia sẻ; ghi tên bài."},{"ten":"B. KHÁM PHÁ – HÌNH THÀNH KIẾN THỨC (15 phút)","gv":"Mục tiêu: HS hình thành kiến thức, kĩ năng trọng tâm của tiết.\n- GV giới thiệu về điệu lí, hát mẫu bài Lí đất giồng; hỏi cảm nhận.\n- GV hướng dẫn đọc lời ca theo tiết tấu, dạy hát nối tiếp từng câu; chú ý luyến, láy đặc trưng dân ca.","hs":"- HS lắng nghe, quan sát, thực hành theo hướng dẫn."},{"ten":"C. LUYỆN TẬP – THỰC HÀNH (10 phút)","gv":"Mục tiêu: HS luyện tập, củng cố kĩ năng vừa học.\n- Cả lớp hát cả bài kết hợp gõ đệm theo nhịp; luyện theo tổ, nhóm, cá nhân.\n- GV sửa sai về cao độ, luyến láy, phát âm.","hs":"- HS luyện tập theo tổ, nhóm, cá nhân; tự nhận xét và sửa sai."},{"ten":"D. VẬN DỤNG (5 phút)","gv":"Mục tiêu: HS vận dụng, sáng tạo và liên hệ thực tế.\n- HS kể tên một làn điệu dân ca em biết ở quê hương mình; hát lại bài cho người thân nghe.","hs":"- HS chia sẻ, biểu diễn; lắng nghe dặn dò."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 2) GV mở bản thu mẫu bài “Lí đất giồng” từ học liệu điện tử của bộ sách, chỉ cho HS dòng ghi tác giả “Dân ca Nam Bộ”; HS nghe trọn bài một lần để nắm giai điệu và chỗ ngân, sau đó nghe từng câu và hát theo, chủ động xin GV mở lại đúng câu mình còn hát chênh.\n- (Miền 3: Sáng tạo nội dung số — Cơ bản, bậc 2) Tập xong, mỗi tổ tự thu âm phần trình bày bài “Lí đất giồng” bằng điện thoại hoặc máy tính của lớp, nghe lại rồi chỉ ra chỗ vào chưa đều, chỗ hát chưa rõ lời để sửa và thu lần thứ hai.\n⚠ (Miền 4: An toàn) Chỉ lấy bản thu từ học liệu của bộ sách hoặc kênh chính thức của nhà xuất bản, không tải nhạc từ trang lạ và không chép nhạc của người khác rồi nhận là của mình; khi giới thiệu bài “Lí đất giồng” phải nêu tên tác giả; bản thu giọng hát của tổ chỉ dùng trong giờ học, muốn gửi cho ai phải hỏi ý kiến cả tổ và GV.","hs":"- HS nghe bản thu mẫu, hát đúng cao độ và biết xin mở lại đúng câu mình còn sai.\n- HS thu âm, nghe lại phần trình bày bài “Lí đất giồng” của tổ và nêu được chỗ đã sửa ở lần thu thứ hai."}]},
{"lop":5,"mon":"Âm nhạc","tuan":6,"tiet":6,"bai":"Chủ đề 2: Giai điệu quê hương — Thường thức âm nhạc: Giới thiệu đàn nhị; Ôn tập bài hát Lí đất giồng","yccd":"1. Năng lực âm nhạc (đặc thù)\n- Nhận biết được hình dáng, âm sắc của đàn nhị; nêu được vài nét về vai trò của đàn nhị trong âm nhạc dân tộc.\n- Hát thuộc, thể hiện đúng sắc thái bài Lí đất giồng; hát kết hợp vận động nhẹ nhàng.\n2. Năng lực chung\n- Tự chủ và tự học: Chủ động tìm hiểu, ghi nhớ đặc điểm đàn nhị.\n- Giao tiếp và hợp tác: Trao đổi, chia sẻ trong nhóm.\n- Giải quyết vấn đề và sáng tạo: Liên hệ âm sắc nhạc cụ với cảm xúc bài hát.\n3. Phẩm chất\n- Yêu quý và tự hào về nhạc cụ, âm nhạc truyền thống dân tộc.\n- Chăm chỉ, trách nhiệm trong học tập.\n4. Tích hợp\n- Năng lực số 1.1 CB2 (Duyệt, tìm kiếm và lọc dữ liệu, thông tin, nội dung số): HS nêu được đặc điểm nổi bật của “Giới thiệu đàn nhị” nhờ quan sát tư liệu số và nghe bản thu.","dodung":"- GV: Máy tính, ti vi/máy chiếu, loa; bài giảng điện tử có hình ảnh, video, âm thanh đàn nhị; đàn phím điện tử; nhạc cụ gõ.\n- HS: SGK Âm nhạc 5 (Kết nối tri thức với cuộc sống), vở ghi.","hoatdong":[{"ten":"A. KHỞI ĐỘNG (5 phút)","gv":"Mục tiêu: Tạo tâm thế vui vẻ, kết nối vào bài học.\n- GV cho lớp hát lại bài Lí đất giồng kết hợp vận động để khởi động.","hs":"- HS hát và vận động theo nhạc."},{"ten":"B. KHÁM PHÁ – HÌNH THÀNH KIẾN THỨC (15 phút)","gv":"Mục tiêu: HS hình thành kiến thức, kĩ năng trọng tâm của tiết.\n- GV giới thiệu hình dáng, cấu tạo, cách chơi đàn nhị qua hình ảnh/video; cho HS nghe âm sắc đàn nhị.\n- GV nêu vài nét về vai trò đàn nhị trong dàn nhạc dân tộc.","hs":"- HS quan sát, lắng nghe, ghi nhớ đặc điểm đàn nhị."},{"ten":"C. LUYỆN TẬP – THỰC HÀNH (10 phút)","gv":"Mục tiêu: HS luyện tập, củng cố kĩ năng vừa học.\n- HS nghe lại âm sắc đàn nhị và nhận biết trong đoạn nhạc GV phát.\n- Ôn bài hát Lí đất giồng theo nhóm; GV sửa sai.","hs":"- HS thực hành nhận biết âm sắc; luyện hát theo nhóm."},{"ten":"D. VẬN DỤNG (5 phút)","gv":"Mục tiêu: HS vận dụng, sáng tạo và liên hệ thực tế.\n- HS nói cảm nhận về âm thanh đàn nhị (buồn/vui/da diết…); kể tên một nhạc cụ dân tộc khác em biết.","hs":"- HS chia sẻ cảm nhận; lắng nghe dặn dò."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 2) GV chiếu đoạn phim quay cận cảnh cho nội dung “Giới thiệu đàn nhị”: nhìn rõ hình dáng, chất liệu, số dây hoặc số lỗ, bàn tay nghệ sĩ đặt ở đâu và làm động tác gì để ra tiếng; GV tua chậm và dừng đúng chỗ đó — chi tiết này tranh in trong sách và một lần nghe trên lớp không cho thấy được.\n- (Miền 5: Giải quyết vấn đề — Cơ bản, bậc 2) HS làm bài tập nghe tương tác có chấm ngay: GV mở lần lượt vài đoạn nhạc ngắn, HS chọn đoạn nào có âm sắc của nhạc cụ vừa học trong “Giới thiệu đàn nhị”; chọn sai thì nghe lại đoạn đó và chọn lần nữa cho tới khi nhận ra đúng.\n⚠ (Miền 4: An toàn) Tư liệu về “Giới thiệu đàn nhị” phải lấy từ trang của nhà xuất bản, nhà hát, bảo tàng hoặc kênh chính thức của nghệ sĩ và tải sẵn về máy trước giờ lên lớp để không lẫn quảng cáo; khi kể lại cho người khác phải nói rõ mình đã xem ở đâu, không nhận tư liệu của người khác là của mình; mở âm lượng vừa đủ nghe.","hs":"- HS nêu được đặc điểm nổi bật của “Giới thiệu đàn nhị” nhờ quan sát tư liệu số và nghe bản thu.\n- HS làm bài tập tương tác, nhận ra âm sắc – nội dung đã học và tự sửa khi chọn sai."}]},
{"lop":5,"mon":"Âm nhạc","tuan":7,"tiet":7,"bai":"Chủ đề 2: Giai điệu quê hương — Nhạc cụ (tiết tấu và giai điệu); Ôn tập bài hát Lí đất giồng","yccd":"1. Năng lực âm nhạc (đặc thù)\n- Biết thể hiện mẫu tiết tấu và bước đầu chơi mẫu giai điệu đơn giản trên nhạc cụ để đệm cho bài Lí đất giồng.\n- Hát kết hợp gõ đệm, thể hiện đúng sắc thái dân ca.\n2. Năng lực chung\n- Tự chủ và tự học: Chủ động luyện tập nhạc cụ, tự sửa sai.\n- Giao tiếp và hợp tác: Phối hợp trong nhóm hoà tấu.\n- Giải quyết vấn đề và sáng tạo: Sáng tạo cách phối hợp hát – gõ – đệm giai điệu.\n3. Phẩm chất\n- Yêu thích nhạc cụ, kiên trì luyện tập.\n- Đoàn kết, trách nhiệm khi hoạt động nhóm.","dodung":"- GV: Máy tính, ti vi/máy chiếu, loa; bài giảng điện tử; đàn phím điện tử; nhạc cụ gõ, nhạc cụ giai điệu (ri-coóc-đơ/kèn phím) nếu có.\n- HS: SGK Âm nhạc 5 (Kết nối tri thức với cuộc sống), vở ghi, nhạc cụ gõ tự tạo nếu có.","hoatdong":[{"ten":"A. KHỞI ĐỘNG (5 phút)","gv":"Mục tiêu: Tạo tâm thế vui vẻ, kết nối vào bài học.\n- GV gõ một mẫu tiết tấu, HS gõ lặp lại (trò chơi tiếng vọng).","hs":"- HS tham gia trò chơi gõ tiết tấu."},{"ten":"B. KHÁM PHÁ – HÌNH THÀNH KIẾN THỨC (15 phút)","gv":"Mục tiêu: HS hình thành kiến thức, kĩ năng trọng tâm của tiết.\n- GV giới thiệu mẫu tiết tấu và mẫu giai điệu đệm cho bài Lí đất giồng; làm mẫu trên nhạc cụ.\n- GV hướng dẫn HS thực hiện từng mẫu; kết hợp gõ đệm với giai điệu.","hs":"- HS quan sát, thực hành theo mẫu."},{"ten":"C. LUYỆN TẬP – THỰC HÀNH (10 phút)","gv":"Mục tiêu: HS luyện tập, củng cố kĩ năng vừa học.\n- HS luyện nhạc cụ theo nhóm; ghép hát với đệm nhạc cụ.\n- GV sửa tiết tấu, cao độ; hướng dẫn phối hợp.","hs":"- HS luyện tập theo nhóm; tự nhận xét và sửa sai."},{"ten":"D. VẬN DỤNG (5 phút)","gv":"Mục tiêu: HS vận dụng, sáng tạo và liên hệ thực tế.\n- Các nhóm biểu diễn hát kết hợp đệm nhạc cụ; nhận xét lẫn nhau.","hs":"- HS biểu diễn nhóm; lắng nghe dặn dò."}]},
{"lop":5,"mon":"Âm nhạc","tuan":8,"tiet":8,"bai":"Chủ đề 2: Giai điệu quê hương — Vận dụng – Sáng tạo (tổng kết chủ đề 2)","yccd":"1. Năng lực âm nhạc (đặc thù)\n- Biểu diễn được bài Lí đất giồng kết hợp gõ đệm/đệm nhạc cụ và vận động; thể hiện đúng sắc thái dân ca.\n- Vận dụng hiểu biết về đàn nhị, dân ca vào biểu diễn và cảm thụ.\n2. Năng lực chung\n- Tự chủ và tự học: Tự tin thể hiện, tự điều chỉnh.\n- Giao tiếp và hợp tác: Phối hợp biểu diễn nhóm nhịp nhàng.\n- Giải quyết vấn đề và sáng tạo: Sáng tạo hình thức biểu diễn tổng hợp.\n3. Phẩm chất\n- Yêu quê hương, tự hào về dân ca dân tộc.\n- Đoàn kết, tự tin, chăm chỉ.","dodung":"- GV: Máy tính, ti vi/máy chiếu, loa; bài giảng điện tử; đàn phím điện tử; nhạc cụ gõ, nhạc cụ giai điệu nếu có.\n- HS: SGK Âm nhạc 5 (Kết nối tri thức với cuộc sống), vở ghi, nhạc cụ gõ tự tạo nếu có.","hoatdong":[{"ten":"A. KHỞI ĐỘNG (5 phút)","gv":"Mục tiêu: Tạo tâm thế vui vẻ, kết nối vào bài học.\n- GV cho lớp hát lại Lí đất giồng và ôn mẫu gõ đệm đã học.","hs":"- HS hát và gõ đệm ôn lại."},{"ten":"B. KHÁM PHÁ – HÌNH THÀNH KIẾN THỨC (15 phút)","gv":"Mục tiêu: HS hình thành kiến thức, kĩ năng trọng tâm của tiết.\n- GV hướng dẫn các nhóm dàn dựng tiết mục tổng hợp: hát – gõ/đệm nhạc cụ – vận động; phân vai trong nhóm.\n- GV gợi ý cách sáng tạo động tác phù hợp dân ca.","hs":"- HS thảo luận, phân vai, dàn dựng tiết mục theo nhóm."},{"ten":"C. LUYỆN TẬP – THỰC HÀNH (10 phút)","gv":"Mục tiêu: HS luyện tập, củng cố kĩ năng vừa học.\n- Các nhóm luyện tập tiết mục; GV góp ý, chỉnh sửa.","hs":"- HS luyện tập tiết mục theo nhóm; tự điều chỉnh."},{"ten":"D. VẬN DỤNG (5 phút)","gv":"Mục tiêu: HS vận dụng, sáng tạo và liên hệ thực tế.\n- Các nhóm biểu diễn khép lại chủ đề 2; cả lớp nhận xét, bình chọn.","hs":"- HS biểu diễn, nhận xét bạn; lắng nghe dặn dò."}]},
{"lop":5,"mon":"Âm nhạc","tuan":9,"tiet":9,"bai":"Ôn tập giữa học kì 1","yccd":"1. Năng lực âm nhạc (đặc thù)\n- Hát thuộc, đúng sắc thái các bài Chim sơn ca, Lí đất giồng; đọc lại Bài đọc nhạc số 1.\n- Củng cố kiến thức trọng âm, phách, vạch nhịp, ô nhịp; nhận biết âm sắc đàn nhị.\n2. Năng lực chung\n- Tự chủ và tự học: Tự ôn tập, hệ thống lại nội dung đã học.\n- Giao tiếp và hợp tác: Ôn luyện, biểu diễn theo nhóm.\n- Giải quyết vấn đề và sáng tạo: Vận dụng linh hoạt kiến thức vào biểu diễn.\n3. Phẩm chất\n- Chăm chỉ ôn tập; tự tin thể hiện.\n- Trách nhiệm, đoàn kết trong nhóm.","dodung":"- GV: Máy tính, ti vi/máy chiếu, loa; bài giảng điện tử tổng hợp nội dung chủ đề 1–2; đàn phím điện tử; nhạc cụ gõ.\n- HS: SGK Âm nhạc 5 (Kết nối tri thức với cuộc sống), vở ghi, nhạc cụ gõ.","hoatdong":[{"ten":"A. KHỞI ĐỘNG (5 phút)","gv":"Mục tiêu: Tạo tâm thế vui vẻ, kết nối vào bài học.\n- GV cho HS chơi trò chơi đoán tên bài hát/nhạc cụ đã học qua đoạn nhạc ngắn.","hs":"- HS tham gia trò chơi, nhớ lại nội dung đã học."},{"ten":"B. KHÁM PHÁ – HÌNH THÀNH KIẾN THỨC (15 phút)","gv":"Mục tiêu: HS hình thành kiến thức, kĩ năng trọng tâm của tiết.\n- GV hệ thống lại kiến thức: bài hát, đọc nhạc, lí thuyết trọng âm–phách, đàn nhị.\n- GV cho HS ôn từng nội dung, chốt lại điểm dễ sai.","hs":"- HS ôn tập, hệ thống kiến thức theo hướng dẫn."},{"ten":"C. LUYỆN TẬP – THỰC HÀNH (10 phút)","gv":"Mục tiêu: HS luyện tập, củng cố kĩ năng vừa học.\n- HS luyện hát, đọc nhạc, gõ đệm theo nhóm; GV sửa sai.","hs":"- HS luyện tập theo nhóm; tự nhận xét, sửa sai."},{"ten":"D. VẬN DỤNG (5 phút)","gv":"Mục tiêu: HS vận dụng, sáng tạo và liên hệ thực tế.\n- Nhóm biểu diễn tổng hợp một nội dung tự chọn; cả lớp nhận xét.","hs":"- HS biểu diễn, nhận xét bạn; lắng nghe dặn dò."}]},
{"lop":5,"mon":"Âm nhạc","tuan":10,"tiet":10,"bai":"Chủ đề 3: Bay vào tương lai — Học hát: Bay vào tương lai","yccd":"1. Năng lực âm nhạc (đặc thù)\n- Hát đúng cao độ, trường độ, lời ca bài Bay vào tương lai; thể hiện tính chất tươi vui, mơ ước, hướng tới tương lai.\n- Biết hát rõ lời, lấy hơi đúng chỗ; hát kết hợp gõ đệm theo nhịp 2/4.\n2. Năng lực chung\n- Tự chủ và tự học: Chủ động luyện tập, tự điều chỉnh.\n- Giao tiếp và hợp tác: Phối hợp trong nhóm; lắng nghe, chia sẻ.\n- Giải quyết vấn đề và sáng tạo: Nghĩ ra động tác, cách gõ đệm phù hợp.\n3. Phẩm chất\n- Có ước mơ, hoài bão, tin tưởng vào tương lai; chăm chỉ học tập.\n- Tích cực tham gia hoạt động ca hát.\n4. Tích hợp\n- Năng lực số 1.1 CB2 (Duyệt, tìm kiếm và lọc dữ liệu, thông tin, nội dung số): HS nghe bản thu mẫu, hát đúng cao độ và biết xin mở lại đúng câu mình còn sai.","dodung":"- GV: Máy tính, ti vi/máy chiếu, loa; bài giảng điện tử có file hát mẫu, hình ảnh minh hoạ; đàn phím điện tử; nhạc cụ gõ.\n- HS: SGK Âm nhạc 5 (Kết nối tri thức với cuộc sống), vở ghi, nhạc cụ gõ.","hoatdong":[{"ten":"A. KHỞI ĐỘNG (5 phút)","gv":"Mục tiêu: Tạo tâm thế vui vẻ, kết nối vào bài học.\n- GV hỏi HS về ước mơ nghề nghiệp tương lai; dẫn vào bài Bay vào tương lai.","hs":"- HS chia sẻ ước mơ; ghi tên bài."},{"ten":"B. KHÁM PHÁ – HÌNH THÀNH KIẾN THỨC (15 phút)","gv":"Mục tiêu: HS hình thành kiến thức, kĩ năng trọng tâm của tiết.\n- GV hát mẫu bài Bay vào tương lai; hỏi cảm nhận.\n- GV hướng dẫn đọc lời ca theo tiết tấu; dạy hát nối tiếp từng câu; nhắc HS hát đúng nhịp 2/4.","hs":"- HS lắng nghe, quan sát, thực hành theo hướng dẫn."},{"ten":"C. LUYỆN TẬP – THỰC HÀNH (10 phút)","gv":"Mục tiêu: HS luyện tập, củng cố kĩ năng vừa học.\n- Cả lớp hát cả bài kết hợp gõ đệm theo nhịp 2/4; luyện theo tổ, nhóm, cá nhân.\n- GV sửa sai về cao độ, tiết tấu, phát âm.","hs":"- HS luyện tập theo tổ, nhóm, cá nhân; tự nhận xét, sửa sai."},{"ten":"D. VẬN DỤNG (5 phút)","gv":"Mục tiêu: HS vận dụng, sáng tạo và liên hệ thực tế.\n- HS hát bài cho người thân nghe; viết/nói một câu về ước mơ của mình.","hs":"- HS chia sẻ ước mơ, biểu diễn; lắng nghe dặn dò."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 2) GV mở bản thu mẫu bài “Bay vào tương lai” từ học liệu điện tử của bộ sách, chỉ cho HS dòng ghi tên tác giả in kèm bản nhạc trong sách; HS nghe trọn bài một lần để nắm giai điệu và chỗ ngân, sau đó nghe từng câu và hát theo, chủ động xin GV mở lại đúng câu mình còn hát chênh.\n- (Miền 3: Sáng tạo nội dung số — Cơ bản, bậc 2) Tập xong, mỗi tổ tự thu âm phần trình bày bài “Bay vào tương lai” bằng điện thoại hoặc máy tính của lớp, nghe lại rồi chỉ ra chỗ vào chưa đều, chỗ hát chưa rõ lời để sửa và thu lần thứ hai.\n⚠ (Miền 4: An toàn) Chỉ lấy bản thu từ học liệu của bộ sách hoặc kênh chính thức của nhà xuất bản, không tải nhạc từ trang lạ và không chép nhạc của người khác rồi nhận là của mình; khi giới thiệu bài “Bay vào tương lai” phải nêu tên tác giả; bản thu giọng hát của tổ chỉ dùng trong giờ học, muốn gửi cho ai phải hỏi ý kiến cả tổ và GV.","hs":"- HS nghe bản thu mẫu, hát đúng cao độ và biết xin mở lại đúng câu mình còn sai.\n- HS thu âm, nghe lại phần trình bày bài “Bay vào tương lai” của tổ và nêu được chỗ đã sửa ở lần thu thứ hai."}]},
{"lop":5,"mon":"Âm nhạc","tuan":11,"tiet":11,"bai":"Chủ đề 3: Bay vào tương lai — Đọc nhạc: Bài số 2 (nhịp 2/4); Ôn tập bài hát Bay vào tương lai","yccd":"1. Năng lực âm nhạc (đặc thù)\n- Đọc đúng cao độ, trường độ Bài đọc nhạc số 2 ở nhịp 2/4; đọc kết hợp gõ phách.\n- Hát thuộc bài Bay vào tương lai; hát kết hợp vận động nhẹ nhàng.\n2. Năng lực chung\n- Tự chủ và tự học: Chủ động luyện đọc nhạc, tự sửa sai.\n- Giao tiếp và hợp tác: Đọc nhạc, biểu diễn theo nhóm.\n- Giải quyết vấn đề và sáng tạo: Ghép đọc nhạc với gõ đệm.\n3. Phẩm chất\n- Chăm chỉ, kiên trì luyện đọc nhạc.\n- Trách nhiệm, hợp tác trong nhóm.\n4. Tích hợp\n- Năng lực số 1.1 CB2 (Duyệt, tìm kiếm và lọc dữ liệu, thông tin, nội dung số): HS đọc đúng cao độ “Bài số 2 (nhịp 2/4)” nhờ nghe mẫu từ đàn phím.","dodung":"- GV: Máy tính, ti vi/máy chiếu, loa; bài giảng điện tử có Bài đọc nhạc số 2; đàn phím điện tử; nhạc cụ gõ.\n- HS: SGK Âm nhạc 5 (Kết nối tri thức với cuộc sống), vở ghi, nhạc cụ gõ.","hoatdong":[{"ten":"A. KHỞI ĐỘNG (5 phút)","gv":"Mục tiêu: Tạo tâm thế vui vẻ, kết nối vào bài học.\n- GV cho HS luyện thanh và ôn nhanh cách đọc tên nốt trên khuông nhạc.","hs":"- HS luyện thanh, nhắc lại tên nốt."},{"ten":"B. KHÁM PHÁ – HÌNH THÀNH KIẾN THỨC (15 phút)","gv":"Mục tiêu: HS hình thành kiến thức, kĩ năng trọng tâm của tiết.\n- GV giới thiệu Bài đọc nhạc số 2 (nhịp 2/4); đọc mẫu.\n- GV hướng dẫn đọc từng câu, đọc kết hợp gõ phách theo nhịp 2/4.","hs":"- HS quan sát, đọc theo mẫu, thực hành từng câu."},{"ten":"C. LUYỆN TẬP – THỰC HÀNH (10 phút)","gv":"Mục tiêu: HS luyện tập, củng cố kĩ năng vừa học.\n- HS đọc cả bài kết hợp gõ phách; luyện theo tổ, nhóm.\n- Ôn bài hát Bay vào tương lai; GV sửa sai.","hs":"- HS luyện tập theo tổ, nhóm, cá nhân; tự nhận xét, sửa sai."},{"ten":"D. VẬN DỤNG (5 phút)","gv":"Mục tiêu: HS vận dụng, sáng tạo và liên hệ thực tế.\n- HS đọc nhạc kết hợp gõ đệm biểu diễn theo nhóm; chia sẻ cảm nhận.","hs":"- HS biểu diễn nhóm; lắng nghe dặn dò."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 2) GV dùng đàn phím điện tử hoặc phần mềm đàn phím lấy cao độ chuẩn cho “Bài số 2 (nhịp 2/4)”: nghe mẫu từng nốt, nghe cả câu ở tốc độ chậm rồi tăng dần; HS chủ động xin nghe lại đúng quãng mình còn đọc chênh thay vì đọc lại cả bài.\n- (Miền 5: Giải quyết vấn đề — Cơ bản, bậc 2) HS luyện “Bài số 2 (nhịp 2/4)” bằng phần mềm đọc nhạc có chấm ngay: máy phát nốt, HS đọc lại, máy báo đúng hay còn cao hơn, thấp hơn; HS xem kết quả để tự chọn quãng cần luyện thêm và đặt mục tiêu cho lần sau.\n⚠ (Miền 4: An toàn) Chỉ mở phần mềm đàn phím và phần mềm đọc nhạc GV đã chỉ định, không mở trang khác trong giờ thực hành; nếu dùng tai nghe thì để âm lượng vừa và không quá 20 phút liên tục; máy chỉ báo được đúng sai về cao độ, còn đọc có mềm mại hay không thì phải nghe bằng tai mình và nghe GV góp ý.","hs":"- HS đọc đúng cao độ “Bài số 2 (nhịp 2/4)” nhờ nghe mẫu từ đàn phím.\n- HS tự xác định quãng mình còn đọc chênh và luyện lại đúng quãng đó."}]},
{"lop":5,"mon":"Âm nhạc","tuan":12,"tiet":12,"bai":"Chủ đề 3: Bay vào tương lai — Nghe nhạc: Đường đến trường vui lắm; Ôn tập bài hát Bay vào tương lai","yccd":"1. Năng lực âm nhạc (đặc thù)\n- Lắng nghe, cảm nhận được tính chất, sắc thái bài Đường đến trường vui lắm; biết vận động theo nhạc.\n- Hát thuộc, biểu diễn tự tin bài Bay vào tương lai.\n2. Năng lực chung\n- Tự chủ và tự học: Chủ động lắng nghe, nêu cảm nhận.\n- Giao tiếp và hợp tác: Chia sẻ cảm nhận, biểu diễn nhóm.\n- Giải quyết vấn đề và sáng tạo: Sáng tạo động tác vận động theo nhạc.\n3. Phẩm chất\n- Yêu trường lớp, bạn bè; lạc quan, yêu đời.\n- Chăm chỉ, tự tin.\n4. Tích hợp\n- Năng lực số 1.1 CB2 (Duyệt, tìm kiếm và lọc dữ liệu, thông tin, nội dung số): HS nêu được nét đặc sắc của tác phẩm “Đường đến trường vui lắm” nhờ vừa nghe vừa quan sát dàn nhạc biểu diễn.","dodung":"- GV: Máy tính, ti vi/máy chiếu, loa; bài giảng điện tử có file bài nghe Đường đến trường vui lắm; đàn phím điện tử; nhạc cụ gõ.\n- HS: SGK Âm nhạc 5 (Kết nối tri thức với cuộc sống), vở ghi.","hoatdong":[{"ten":"A. KHỞI ĐỘNG (5 phút)","gv":"Mục tiêu: Tạo tâm thế vui vẻ, kết nối vào bài học.\n- GV cho lớp hát lại Bay vào tương lai để khởi động.","hs":"- HS hát khởi động."},{"ten":"B. KHÁM PHÁ – HÌNH THÀNH KIẾN THỨC (15 phút)","gv":"Mục tiêu: HS hình thành kiến thức, kĩ năng trọng tâm của tiết.\n- GV cho HS nghe bài Đường đến trường vui lắm, gợi ý chú ý nhịp điệu, sắc thái.\n- GV đặt câu hỏi về cảm nhận; giới thiệu ngắn nội dung bài nghe.","hs":"- HS lắng nghe, cảm nhận, trả lời câu hỏi."},{"ten":"C. LUYỆN TẬP – THỰC HÀNH (10 phút)","gv":"Mục tiêu: HS luyện tập, củng cố kĩ năng vừa học.\n- HS nghe lại bài và vận động cơ thể theo nhịp; ôn biểu diễn Bay vào tương lai theo nhóm.\n- GV sửa sai, hướng dẫn vận động.","hs":"- HS vận động theo nhạc; luyện biểu diễn nhóm."},{"ten":"D. VẬN DỤNG (5 phút)","gv":"Mục tiêu: HS vận dụng, sáng tạo và liên hệ thực tế.\n- HS nói cảm nhận sau khi nghe; kể một kỉ niệm vui trên đường đến trường.","hs":"- HS chia sẻ; lắng nghe dặn dò."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 2) GV mở bản ghi hình buổi biểu diễn tác phẩm “Đường đến trường vui lắm”; HS vừa nghe vừa quan sát để nhận ra nhạc cụ nào giữ giai điệu chính, đoạn nào nhạc mạnh lên, đoạn nào chậm lại và ai là người bắt nhịp cho cả dàn nhạc — những điều chỉ nghe bản thu tiếng thì không thấy được.\n- (Miền 6: Ứng dụng trí tuệ nhân tạo — Cơ bản, bậc 2) GV mở thêm một đoạn nhạc do máy tự sinh theo phong cách gần giống rồi cho HS nghe đối chiếu với bản do nghệ sĩ biểu diễn; HS nêu chỗ khác nhau về sắc thái to nhỏ, chỗ nhanh chậm và nhận ra máy ghép lại theo những bản nhạc nó đã học nên chưa có cảm xúc của người chơi. GV mở và điều khiển công cụ, HS nghe và nhận xét.\n⚠ (Miền 4: An toàn) Bản ghi hình “Đường đến trường vui lắm” phải lấy từ kênh chính thức của nhà hát, dàn nhạc hoặc nhà xuất bản và tải về trước để không lẫn quảng cáo; khi nói hoặc viết về tác phẩm phải ghi tên tác giả và tên người biểu diễn, không cắt nhạc của người khác đem dùng khi chưa được phép; nghe bằng loa ở mức vừa, không đeo tai nghe mở to lâu.","hs":"- HS nêu được nét đặc sắc của tác phẩm “Đường đến trường vui lắm” nhờ vừa nghe vừa quan sát dàn nhạc biểu diễn.\n- HS chỉ ra được điểm khác giữa đoạn nhạc do máy tạo và đoạn do nghệ sĩ trình bày."}]},
{"lop":5,"mon":"Âm nhạc","tuan":13,"tiet":13,"bai":"Chủ đề 3: Bay vào tương lai — Nhạc cụ; Vận dụng – Sáng tạo (tổng kết chủ đề 3)","yccd":"1. Năng lực âm nhạc (đặc thù)\n- Biết thể hiện mẫu tiết tấu/giai điệu đơn giản trên nhạc cụ để đệm cho bài Bay vào tương lai.\n- Biểu diễn tổng hợp hát – gõ đệm – vận động; thể hiện đúng sắc thái tươi vui.\n2. Năng lực chung\n- Tự chủ và tự học: Chủ động luyện nhạc cụ.\n- Giao tiếp và hợp tác: Phối hợp trong nhóm hoà tấu, biểu diễn.\n- Giải quyết vấn đề và sáng tạo: Sáng tạo hình thức biểu diễn tổng hợp.\n3. Phẩm chất\n- Tự tin, lạc quan; đoàn kết, chăm chỉ.","dodung":"- GV: Máy tính, ti vi/máy chiếu, loa; bài giảng điện tử; đàn phím điện tử; nhạc cụ gõ, nhạc cụ giai điệu nếu có.\n- HS: SGK Âm nhạc 5 (Kết nối tri thức với cuộc sống), vở ghi, nhạc cụ gõ tự tạo nếu có.","hoatdong":[{"ten":"A. KHỞI ĐỘNG (5 phút)","gv":"Mục tiêu: Tạo tâm thế vui vẻ, kết nối vào bài học.\n- GV gõ mẫu tiết tấu, HS gõ lặp (trò chơi tiếng vọng) để ôn nhịp 2/4.","hs":"- HS tham gia trò chơi gõ tiết tấu."},{"ten":"B. KHÁM PHÁ – HÌNH THÀNH KIẾN THỨC (15 phút)","gv":"Mục tiêu: HS hình thành kiến thức, kĩ năng trọng tâm của tiết.\n- GV giới thiệu mẫu tiết tấu/giai điệu đệm cho bài Bay vào tương lai; làm mẫu trên nhạc cụ.\n- Hướng dẫn HS thực hiện từng mẫu; kết hợp đệm với hát.","hs":"- HS quan sát, thực hành sử dụng nhạc cụ theo mẫu."},{"ten":"C. LUYỆN TẬP – THỰC HÀNH (10 phút)","gv":"Mục tiêu: HS luyện tập, củng cố kĩ năng vừa học.\n- HS luyện đệm nhạc cụ theo nhóm; ghép hát với đệm.\n- GV sửa tiết tấu, hướng dẫn phối hợp.","hs":"- HS luyện tập theo nhóm; tự nhận xét, sửa sai."},{"ten":"D. VẬN DỤNG (5 phút)","gv":"Mục tiêu: HS vận dụng, sáng tạo và liên hệ thực tế.\n- Các nhóm biểu diễn tổng hợp khép lại chủ đề 3; cả lớp nhận xét, bình chọn.","hs":"- HS biểu diễn, nhận xét bạn; lắng nghe dặn dò."}]},
{"lop":5,"mon":"Âm nhạc","tuan":14,"tiet":14,"bai":"Chủ đề 4: Chào mùa xuân đến — Học hát: Duyên dáng mùa xuân","yccd":"1. Năng lực âm nhạc (đặc thù)\n- Hát đúng cao độ, trường độ, lời ca bài Duyên dáng mùa xuân; thể hiện tính chất vui tươi, rộn ràng của mùa xuân.\n- Biết hát rõ lời, lấy hơi đúng chỗ; hát kết hợp gõ đệm theo phách.\n2. Năng lực chung\n- Tự chủ và tự học: Chủ động luyện tập, tự điều chỉnh.\n- Giao tiếp và hợp tác: Phối hợp trong nhóm; lắng nghe, chia sẻ.\n- Giải quyết vấn đề và sáng tạo: Nghĩ động tác, cách gõ đệm phù hợp.\n3. Phẩm chất\n- Yêu thiên nhiên, yêu mùa xuân, yêu quê hương đất nước.\n- Chăm chỉ, tích cực tham gia ca hát.\n4. Tích hợp\n- Năng lực số 1.1 CB2 (Duyệt, tìm kiếm và lọc dữ liệu, thông tin, nội dung số): HS nghe bản thu mẫu, hát đúng cao độ và biết xin mở lại đúng câu mình còn sai.","dodung":"- GV: Máy tính, ti vi/máy chiếu, loa; bài giảng điện tử có file hát mẫu, hình ảnh mùa xuân; đàn phím điện tử; nhạc cụ gõ.\n- HS: SGK Âm nhạc 5 (Kết nối tri thức với cuộc sống), vở ghi, nhạc cụ gõ.","hoatdong":[{"ten":"A. KHỞI ĐỘNG (5 phút)","gv":"Mục tiêu: Tạo tâm thế vui vẻ, kết nối vào bài học.\n- GV cho HS xem hình ảnh mùa xuân (hoa đào, hoa mai, Tết) và hỏi cảm nhận; dẫn vào bài.","hs":"- HS quan sát, chia sẻ; ghi tên bài."},{"ten":"B. KHÁM PHÁ – HÌNH THÀNH KIẾN THỨC (15 phút)","gv":"Mục tiêu: HS hình thành kiến thức, kĩ năng trọng tâm của tiết.\n- GV hát mẫu bài Duyên dáng mùa xuân; hỏi cảm nhận.\n- Hướng dẫn đọc lời ca theo tiết tấu; dạy hát nối tiếp từng câu; nhắc lấy hơi, hát rõ lời.","hs":"- HS lắng nghe, quan sát, thực hành theo hướng dẫn."},{"ten":"C. LUYỆN TẬP – THỰC HÀNH (10 phút)","gv":"Mục tiêu: HS luyện tập, củng cố kĩ năng vừa học.\n- Cả lớp hát cả bài kết hợp gõ đệm theo phách; luyện theo tổ, nhóm, cá nhân.\n- GV sửa sai về cao độ, tiết tấu, phát âm.","hs":"- HS luyện tập theo tổ, nhóm, cá nhân; tự nhận xét, sửa sai."},{"ten":"D. VẬN DỤNG (5 phút)","gv":"Mục tiêu: HS vận dụng, sáng tạo và liên hệ thực tế.\n- HS hát bài cho người thân nghe dịp Tết; kể một hoạt động ngày Tết em thích.","hs":"- HS chia sẻ, biểu diễn; lắng nghe dặn dò."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 2) GV mở bản thu mẫu bài “Duyên dáng mùa xuân” từ học liệu điện tử của bộ sách, chỉ cho HS dòng ghi tên tác giả in kèm bản nhạc trong sách; HS nghe trọn bài một lần để nắm giai điệu và chỗ ngân, sau đó nghe từng câu và hát theo, chủ động xin GV mở lại đúng câu mình còn hát chênh.\n- (Miền 3: Sáng tạo nội dung số — Cơ bản, bậc 2) Tập xong, mỗi tổ tự thu âm phần trình bày bài “Duyên dáng mùa xuân” bằng điện thoại hoặc máy tính của lớp, nghe lại rồi chỉ ra chỗ vào chưa đều, chỗ hát chưa rõ lời để sửa và thu lần thứ hai.\n⚠ (Miền 4: An toàn) Chỉ lấy bản thu từ học liệu của bộ sách hoặc kênh chính thức của nhà xuất bản, không tải nhạc từ trang lạ và không chép nhạc của người khác rồi nhận là của mình; khi giới thiệu bài “Duyên dáng mùa xuân” phải nêu tên tác giả; bản thu giọng hát của tổ chỉ dùng trong giờ học, muốn gửi cho ai phải hỏi ý kiến cả tổ và GV.","hs":"- HS nghe bản thu mẫu, hát đúng cao độ và biết xin mở lại đúng câu mình còn sai.\n- HS thu âm, nghe lại phần trình bày bài “Duyên dáng mùa xuân” của tổ và nêu được chỗ đã sửa ở lần thu thứ hai."}]},
{"lop":5,"mon":"Âm nhạc","tuan":15,"tiet":15,"bai":"Chủ đề 4: Chào mùa xuân đến — Thường thức âm nhạc: Bản Xô-nát Ánh trăng (Beethoven); Ôn tập bài hát Duyên dáng mùa xuân","yccd":"1. Năng lực âm nhạc (đặc thù)\n- Nghe và cảm nhận được tính chất của bản Xô-nát Ánh trăng; biết vài nét về nhạc sĩ Beethoven và tác phẩm.\n- Hát thuộc, thể hiện đúng sắc thái bài Duyên dáng mùa xuân.\n2. Năng lực chung\n- Tự chủ và tự học: Chủ động lắng nghe, tìm hiểu, ghi nhớ.\n- Giao tiếp và hợp tác: Trao đổi, chia sẻ cảm nhận trong nhóm.\n- Giải quyết vấn đề và sáng tạo: Liên hệ âm nhạc với cảm xúc, hình ảnh.\n3. Phẩm chất\n- Yêu thích, trân trọng âm nhạc thế giới và tấm gương lao động nghệ thuật của nhạc sĩ.\n- Chăm chỉ, kiên trì học tập.\n4. Tích hợp\n- Năng lực số 1.1 CB2 (Duyệt, tìm kiếm và lọc dữ liệu, thông tin, nội dung số): HS nêu được đặc điểm nổi bật của “Bản Xô-nát Ánh trăng (Beethoven)” nhờ quan sát tư liệu số và nghe bản thu.","dodung":"- GV: Máy tính, ti vi/máy chiếu, loa; bài giảng điện tử có file nghe Xô-nát Ánh trăng, hình ảnh nhạc sĩ Beethoven; đàn phím điện tử.\n- HS: SGK Âm nhạc 5 (Kết nối tri thức với cuộc sống), vở ghi.","hoatdong":[{"ten":"A. KHỞI ĐỘNG (5 phút)","gv":"Mục tiêu: Tạo tâm thế vui vẻ, kết nối vào bài học.\n- GV cho lớp hát lại Duyên dáng mùa xuân để khởi động.","hs":"- HS hát khởi động."},{"ten":"B. KHÁM PHÁ – HÌNH THÀNH KIẾN THỨC (15 phút)","gv":"Mục tiêu: HS hình thành kiến thức, kĩ năng trọng tâm của tiết.\n- GV giới thiệu vài nét về nhạc sĩ Beethoven và bản Xô-nát Ánh trăng; cho HS nghe một đoạn.\n- GV gợi ý HS chú ý tính chất êm dịu, sâu lắng của bản nhạc.","hs":"- HS lắng nghe, cảm nhận, ghi nhớ vài nét về tác giả, tác phẩm."},{"ten":"C. LUYỆN TẬP – THỰC HÀNH (10 phút)","gv":"Mục tiêu: HS luyện tập, củng cố kĩ năng vừa học.\n- HS nghe lại đoạn nhạc và nêu cảm nhận; ôn bài hát Duyên dáng mùa xuân theo nhóm.\n- GV sửa sai bài hát.","hs":"- HS lắng nghe, chia sẻ cảm nhận; luyện hát theo nhóm."},{"ten":"D. VẬN DỤNG (5 phút)","gv":"Mục tiêu: HS vận dụng, sáng tạo và liên hệ thực tế.\n- HS vẽ/mô tả bằng lời hình ảnh em tưởng tượng khi nghe bản Ánh trăng.","hs":"- HS chia sẻ tưởng tượng; lắng nghe dặn dò."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 2) GV chiếu vài đoạn phim ngắn cho nội dung “Bản Xô-nát Ánh trăng (Beethoven)”, mỗi đoạn một cách trình bày khác nhau, đặt cạnh nhau trên cùng màn hình; HS so sánh số người tham gia, cách đứng, cách vào bài và chỉ ra điểm khác nhau — xem trực tiếp nhiều đoạn trong vài phút là điều lời giảng suông không thay được.\n- (Miền 5: Giải quyết vấn đề — Cơ bản, bậc 2) HS làm bài tập tương tác có chấm ngay về “Bản Xô-nát Ánh trăng (Beethoven)”: nghe một đoạn rồi chọn đúng tên cách trình bày, nối tên với hình minh hoạ; chọn sai thì xem lại đoạn phim tương ứng rồi chọn lần nữa.\n⚠ (Miền 4: An toàn) Tư liệu về “Bản Xô-nát Ánh trăng (Beethoven)” phải lấy từ trang của nhà xuất bản, nhà hát, bảo tàng hoặc kênh chính thức của nghệ sĩ và tải sẵn về máy trước giờ lên lớp để không lẫn quảng cáo; khi kể lại cho người khác phải nói rõ mình đã xem ở đâu, không nhận tư liệu của người khác là của mình; mở âm lượng vừa đủ nghe.","hs":"- HS nêu được đặc điểm nổi bật của “Bản Xô-nát Ánh trăng (Beethoven)” nhờ quan sát tư liệu số và nghe bản thu.\n- HS làm bài tập tương tác, nhận ra âm sắc – nội dung đã học và tự sửa khi chọn sai."}]},
{"lop":5,"mon":"Âm nhạc","tuan":16,"tiet":16,"bai":"Chủ đề 4: Chào mùa xuân đến — Nhạc cụ; Ôn tập bài hát Duyên dáng mùa xuân","yccd":"1. Năng lực âm nhạc (đặc thù)\n- Biết thể hiện mẫu tiết tấu/giai điệu đơn giản trên nhạc cụ để đệm cho bài Duyên dáng mùa xuân.\n- Hát kết hợp đệm nhạc cụ, thể hiện đúng sắc thái vui tươi mùa xuân.\n2. Năng lực chung\n- Tự chủ và tự học: Chủ động luyện nhạc cụ, tự sửa sai.\n- Giao tiếp và hợp tác: Phối hợp trong nhóm hoà tấu.\n- Giải quyết vấn đề và sáng tạo: Sáng tạo cách phối hợp hát – đệm.\n3. Phẩm chất\n- Yêu thích nhạc cụ, kiên trì luyện tập.\n- Đoàn kết, trách nhiệm.","dodung":"- GV: Máy tính, ti vi/máy chiếu, loa; bài giảng điện tử; đàn phím điện tử; nhạc cụ gõ, nhạc cụ giai điệu nếu có.\n- HS: SGK Âm nhạc 5 (Kết nối tri thức với cuộc sống), vở ghi, nhạc cụ gõ tự tạo nếu có.","hoatdong":[{"ten":"A. KHỞI ĐỘNG (5 phút)","gv":"Mục tiêu: Tạo tâm thế vui vẻ, kết nối vào bài học.\n- GV gõ mẫu tiết tấu, HS gõ lặp lại để khởi động.","hs":"- HS tham gia trò chơi gõ tiết tấu."},{"ten":"B. KHÁM PHÁ – HÌNH THÀNH KIẾN THỨC (15 phút)","gv":"Mục tiêu: HS hình thành kiến thức, kĩ năng trọng tâm của tiết.\n- GV giới thiệu mẫu tiết tấu/giai điệu đệm cho bài Duyên dáng mùa xuân; làm mẫu.\n- Hướng dẫn HS thực hiện từng mẫu; kết hợp đệm với hát.","hs":"- HS quan sát, thực hành sử dụng nhạc cụ theo mẫu."},{"ten":"C. LUYỆN TẬP – THỰC HÀNH (10 phút)","gv":"Mục tiêu: HS luyện tập, củng cố kĩ năng vừa học.\n- HS luyện đệm nhạc cụ theo nhóm; ghép hát với đệm; GV sửa sai.","hs":"- HS luyện tập theo nhóm; tự nhận xét, sửa sai."},{"ten":"D. VẬN DỤNG (5 phút)","gv":"Mục tiêu: HS vận dụng, sáng tạo và liên hệ thực tế.\n- Các nhóm biểu diễn hát kết hợp đệm nhạc cụ; nhận xét lẫn nhau.","hs":"- HS biểu diễn nhóm; lắng nghe dặn dò."}]},
{"lop":5,"mon":"Âm nhạc","tuan":17,"tiet":17,"bai":"Chủ đề 4: Chào mùa xuân đến — Vận dụng – Sáng tạo (tổng kết chủ đề 4)","yccd":"1. Năng lực âm nhạc (đặc thù)\n- Biểu diễn tổng hợp bài Duyên dáng mùa xuân kết hợp đệm nhạc cụ và vận động.\n- Vận dụng cảm thụ bản Xô-nát Ánh trăng vào việc nêu cảm nhận âm nhạc.\n2. Năng lực chung\n- Tự chủ và tự học: Tự tin thể hiện, tự điều chỉnh.\n- Giao tiếp và hợp tác: Phối hợp biểu diễn nhóm nhịp nhàng.\n- Giải quyết vấn đề và sáng tạo: Sáng tạo hình thức biểu diễn tổng hợp.\n3. Phẩm chất\n- Yêu mùa xuân, yêu cuộc sống; tự tin, đoàn kết, chăm chỉ.","dodung":"- GV: Máy tính, ti vi/máy chiếu, loa; bài giảng điện tử; đàn phím điện tử; nhạc cụ gõ, nhạc cụ giai điệu nếu có.\n- HS: SGK Âm nhạc 5 (Kết nối tri thức với cuộc sống), vở ghi, nhạc cụ gõ tự tạo nếu có.","hoatdong":[{"ten":"A. KHỞI ĐỘNG (5 phút)","gv":"Mục tiêu: Tạo tâm thế vui vẻ, kết nối vào bài học.\n- GV cho lớp hát lại Duyên dáng mùa xuân và ôn mẫu gõ đệm.","hs":"- HS hát và gõ đệm ôn lại."},{"ten":"B. KHÁM PHÁ – HÌNH THÀNH KIẾN THỨC (15 phút)","gv":"Mục tiêu: HS hình thành kiến thức, kĩ năng trọng tâm của tiết.\n- GV hướng dẫn nhóm dàn dựng tiết mục tổng hợp: hát – đệm nhạc cụ – vận động; phân vai.\n- Gợi ý sáng tạo động tác mô phỏng không khí mùa xuân.","hs":"- HS thảo luận, phân vai, dàn dựng tiết mục."},{"ten":"C. LUYỆN TẬP – THỰC HÀNH (10 phút)","gv":"Mục tiêu: HS luyện tập, củng cố kĩ năng vừa học.\n- Các nhóm luyện tập tiết mục; GV góp ý, chỉnh sửa.","hs":"- HS luyện tập tiết mục theo nhóm; tự điều chỉnh."},{"ten":"D. VẬN DỤNG (5 phút)","gv":"Mục tiêu: HS vận dụng, sáng tạo và liên hệ thực tế.\n- Các nhóm biểu diễn khép lại chủ đề 4; cả lớp nhận xét, bình chọn.","hs":"- HS biểu diễn, nhận xét bạn; lắng nghe dặn dò."}]},
{"lop":5,"mon":"Âm nhạc","tuan":18,"tiet":18,"bai":"Ôn tập và kiểm tra cuối học kì 1","yccd":"1. Năng lực âm nhạc (đặc thù)\n- Hát thuộc, biểu diễn tự tin các bài đã học (Chim sơn ca, Lí đất giồng, Bay vào tương lai, Duyên dáng mùa xuân); đọc lại các bài đọc nhạc số 1, 2.\n- Củng cố kiến thức lí thuyết, nhận biết nhạc cụ, cảm thụ bài nghe đã học.\n2. Năng lực chung\n- Tự chủ và tự học: Tự ôn tập, hệ thống kiến thức học kì 1.\n- Giao tiếp và hợp tác: Biểu diễn, đánh giá lẫn nhau.\n- Giải quyết vấn đề và sáng tạo: Vận dụng linh hoạt kiến thức vào biểu diễn.\n3. Phẩm chất\n- Chăm chỉ, tự tin, trung thực khi tự đánh giá.\n- Đoàn kết, trách nhiệm.\n4. Tích hợp\n- Năng lực số 3.2 CB2 (Tích hợp và tinh chỉnh nội dung số): HS tự quay, xem lại và nêu được điều tổ mình đã sửa được giữa hai lần trình bày.","dodung":"- GV: Máy tính, ti vi/máy chiếu, loa; bài giảng điện tử tổng hợp học kì 1; đàn phím điện tử; nhạc cụ gõ; phiếu đánh giá.\n- HS: SGK Âm nhạc 5 (Kết nối tri thức với cuộc sống), vở ghi, nhạc cụ gõ.","hoatdong":[{"ten":"A. KHỞI ĐỘNG (5 phút)","gv":"Mục tiêu: Tạo tâm thế vui vẻ, kết nối vào bài học.\n- GV cho HS chơi trò chơi đoán tên bài hát qua giai điệu để ôn lại học kì 1.","hs":"- HS tham gia trò chơi, nhớ lại nội dung đã học."},{"ten":"B. KHÁM PHÁ – HÌNH THÀNH KIẾN THỨC (15 phút)","gv":"Mục tiêu: HS hình thành kiến thức, kĩ năng trọng tâm của tiết.\n- GV hệ thống lại các mạch nội dung học kì 1: hát, đọc nhạc, lí thuyết, nhạc cụ, nghe nhạc, thường thức.\n- GV nêu tiêu chí đánh giá phần biểu diễn.","hs":"- HS ôn tập, nắm tiêu chí đánh giá."},{"ten":"C. LUYỆN TẬP – THỰC HÀNH (10 phút)","gv":"Mục tiêu: HS luyện tập, củng cố kĩ năng vừa học.\n- HS biểu diễn theo nhóm/cá nhân nội dung tự chọn; GV đánh giá theo tiêu chí.","hs":"- HS biểu diễn; tự đánh giá và đánh giá bạn."},{"ten":"D. VẬN DỤNG (5 phút)","gv":"Mục tiêu: HS vận dụng, sáng tạo và liên hệ thực tế.\n- GV nhận xét chung, tuyên dương; HS nêu bài/hoạt động em yêu thích nhất học kì 1.","hs":"- HS chia sẻ; lắng nghe dặn dò chuẩn bị học kì 2."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 3: Sáng tạo nội dung số — Cơ bản, bậc 2) Mỗi tổ tự quay lại phần biểu diễn học kì I của mình bằng điện thoại hoặc máy tính của lớp, xem lại và ghi ra hai điều tổ đã làm tốt, một điều cần sửa, rồi quay lần hai để đối chiếu xem đã khá hơn ở chỗ nào.\n- (Miền 5: Giải quyết vấn đề — Cơ bản, bậc 2) HS làm bộ câu hỏi tương tác có chấm ngay ôn lại học kì I: nghe đoạn nhạc nhận ra bài hát, đọc kí hiệu ghi nhạc, gọi tên nhạc cụ qua âm sắc; HS tự nhìn kết quả để biết phần nào mình còn sai nhiều mà ôn lại đúng phần đó.\n- (Miền 2: Giao tiếp và hợp tác trong môi trường số — Cơ bản, bậc 2) Các tổ đổi bản quay cho nhau qua nhóm lớp và viết cho tổ bạn hai câu nhận xét: một câu khen chỗ bạn làm tốt, một câu góp ý chỗ nên sửa; HS tập viết nhận xét trên nhóm đúng mực như khi nói trực tiếp với bạn.\n⚠ (Miền 4: An toàn) Đoạn phim có mặt bạn chỉ được gửi khi từng bạn trong đó đồng ý và chỉ gửi trong nhóm lớp, không đăng ra mạng xã hội; giới thiệu bài hát phải ghi tên tác giả, không nhận bài của người khác là của mình; góp ý cho bạn bằng lời lịch sự, viết trong nhóm cũng phải như nói trước mặt.","hs":"- HS tự quay, xem lại và nêu được điều tổ mình đã sửa được giữa hai lần trình bày.\n- HS giới thiệu sản phẩm của tổ đúng phép lịch sự, có ghi tên tác giả và xin phép bạn trước khi chia sẻ."}]},
{"lop":5,"mon":"Âm nhạc","tuan":19,"tiet":19,"bai":"Chủ đề 5: Thiên nhiên tươi đẹp — Học hát: Em đi giữa biển vàng","yccd":"1. Năng lực âm nhạc (đặc thù)\n- Hát đúng cao độ, trường độ, lời ca bài Em đi giữa biển vàng; thể hiện tính chất mượt mà, êm ả, giàu hình ảnh.\n- Biết hát rõ lời, lấy hơi đúng chỗ; hát kết hợp gõ đệm theo nhịp 3/4.\n2. Năng lực chung\n- Tự chủ và tự học: Chủ động luyện tập, tự điều chỉnh.\n- Giao tiếp và hợp tác: Phối hợp trong nhóm; lắng nghe, chia sẻ.\n- Giải quyết vấn đề và sáng tạo: Nghĩ động tác, cách gõ đệm phù hợp nhịp 3/4.\n3. Phẩm chất\n- Yêu thiên nhiên, yêu quê hương, yêu cánh đồng lúa quê mình.\n- Chăm chỉ, tích cực tham gia ca hát.\n4. Tích hợp\n- Năng lực số 1.1 CB2 (Duyệt, tìm kiếm và lọc dữ liệu, thông tin, nội dung số): HS nghe bản thu mẫu, hát đúng cao độ và biết xin mở lại đúng câu mình còn sai.","dodung":"- GV: Máy tính, ti vi/máy chiếu, loa; bài giảng điện tử có file hát mẫu, hình ảnh cánh đồng lúa; đàn phím điện tử; nhạc cụ gõ.\n- HS: SGK Âm nhạc 5 (Kết nối tri thức với cuộc sống), vở ghi, nhạc cụ gõ.","hoatdong":[{"ten":"A. KHỞI ĐỘNG (5 phút)","gv":"Mục tiêu: Tạo tâm thế vui vẻ, kết nối vào bài học.\n- GV cho HS xem hình ảnh cánh đồng lúa chín và hỏi cảm nhận; dẫn vào bài.","hs":"- HS quan sát, chia sẻ; ghi tên bài."},{"ten":"B. KHÁM PHÁ – HÌNH THÀNH KIẾN THỨC (15 phút)","gv":"Mục tiêu: HS hình thành kiến thức, kĩ năng trọng tâm của tiết.\n- GV hát mẫu bài Em đi giữa biển vàng; hỏi cảm nhận.\n- Hướng dẫn đọc lời ca theo tiết tấu; dạy hát nối tiếp từng câu; nhắc hát nhẹ nhàng, đúng nhịp 3/4.","hs":"- HS lắng nghe, quan sát, thực hành theo hướng dẫn."},{"ten":"C. LUYỆN TẬP – THỰC HÀNH (10 phút)","gv":"Mục tiêu: HS luyện tập, củng cố kĩ năng vừa học.\n- Cả lớp hát cả bài kết hợp gõ đệm theo nhịp 3/4; luyện theo tổ, nhóm, cá nhân.\n- GV sửa sai về cao độ, tiết tấu, phát âm.","hs":"- HS luyện tập theo tổ, nhóm, cá nhân; tự nhận xét, sửa sai."},{"ten":"D. VẬN DỤNG (5 phút)","gv":"Mục tiêu: HS vận dụng, sáng tạo và liên hệ thực tế.\n- HS hát bài cho người thân nghe; kể một cảnh thiên nhiên quê hương em yêu thích.","hs":"- HS chia sẻ, biểu diễn; lắng nghe dặn dò."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 2) GV mở bản thu mẫu bài “Em đi giữa biển vàng” từ học liệu điện tử của bộ sách, chỉ cho HS dòng ghi tên tác giả in kèm bản nhạc trong sách; HS nghe trọn bài một lần để nắm giai điệu và chỗ ngân, sau đó nghe từng câu và hát theo, chủ động xin GV mở lại đúng câu mình còn hát chênh.\n- (Miền 3: Sáng tạo nội dung số — Cơ bản, bậc 2) Tập xong, mỗi tổ tự thu âm phần trình bày bài “Em đi giữa biển vàng” bằng điện thoại hoặc máy tính của lớp, nghe lại rồi chỉ ra chỗ vào chưa đều, chỗ hát chưa rõ lời để sửa và thu lần thứ hai.\n⚠ (Miền 4: An toàn) Chỉ lấy bản thu từ học liệu của bộ sách hoặc kênh chính thức của nhà xuất bản, không tải nhạc từ trang lạ và không chép nhạc của người khác rồi nhận là của mình; khi giới thiệu bài “Em đi giữa biển vàng” phải nêu tên tác giả; bản thu giọng hát của tổ chỉ dùng trong giờ học, muốn gửi cho ai phải hỏi ý kiến cả tổ và GV.","hs":"- HS nghe bản thu mẫu, hát đúng cao độ và biết xin mở lại đúng câu mình còn sai.\n- HS thu âm, nghe lại phần trình bày bài “Em đi giữa biển vàng” của tổ và nêu được chỗ đã sửa ở lần thu thứ hai."}]},
{"lop":5,"mon":"Âm nhạc","tuan":20,"tiet":20,"bai":"Chủ đề 5: Thiên nhiên tươi đẹp — Đọc nhạc: Bài số 3 (nhịp 3/4); Ôn tập bài hát Em đi giữa biển vàng","yccd":"1. Năng lực âm nhạc (đặc thù)\n- Đọc đúng cao độ, trường độ Bài đọc nhạc số 3 ở nhịp 3/4; đọc kết hợp gõ phách.\n- Hát thuộc bài Em đi giữa biển vàng; hát kết hợp vận động nhẹ nhàng theo nhịp 3/4.\n2. Năng lực chung\n- Tự chủ và tự học: Chủ động luyện đọc nhạc, tự sửa sai.\n- Giao tiếp và hợp tác: Đọc nhạc, biểu diễn theo nhóm.\n- Giải quyết vấn đề và sáng tạo: Ghép đọc nhạc với gõ đệm nhịp 3/4.\n3. Phẩm chất\n- Chăm chỉ, kiên trì luyện đọc nhạc.\n- Trách nhiệm, hợp tác trong nhóm.\n4. Tích hợp\n- Năng lực số 1.1 CB2 (Duyệt, tìm kiếm và lọc dữ liệu, thông tin, nội dung số): HS đọc đúng cao độ “Bài số 3 (nhịp 3/4)” nhờ nghe mẫu từ đàn phím.","dodung":"- GV: Máy tính, ti vi/máy chiếu, loa; bài giảng điện tử có Bài đọc nhạc số 3; đàn phím điện tử; nhạc cụ gõ.\n- HS: SGK Âm nhạc 5 (Kết nối tri thức với cuộc sống), vở ghi, nhạc cụ gõ.","hoatdong":[{"ten":"A. KHỞI ĐỘNG (5 phút)","gv":"Mục tiêu: Tạo tâm thế vui vẻ, kết nối vào bài học.\n- GV cho HS luyện thanh và ôn nhanh cảm nhận nhịp 3/4 (đếm 1-2-3).","hs":"- HS luyện thanh, đếm nhịp 3/4."},{"ten":"B. KHÁM PHÁ – HÌNH THÀNH KIẾN THỨC (15 phút)","gv":"Mục tiêu: HS hình thành kiến thức, kĩ năng trọng tâm của tiết.\n- GV giới thiệu Bài đọc nhạc số 3 (nhịp 3/4); đọc mẫu.\n- Hướng dẫn đọc từng câu, đọc kết hợp gõ phách theo nhịp 3/4.","hs":"- HS quan sát, đọc theo mẫu, thực hành từng câu."},{"ten":"C. LUYỆN TẬP – THỰC HÀNH (10 phút)","gv":"Mục tiêu: HS luyện tập, củng cố kĩ năng vừa học.\n- HS đọc cả bài kết hợp gõ phách; luyện theo tổ, nhóm.\n- Ôn bài hát Em đi giữa biển vàng; GV sửa sai.","hs":"- HS luyện tập theo tổ, nhóm, cá nhân; tự nhận xét, sửa sai."},{"ten":"D. VẬN DỤNG (5 phút)","gv":"Mục tiêu: HS vận dụng, sáng tạo và liên hệ thực tế.\n- HS đọc nhạc kết hợp gõ đệm biểu diễn theo nhóm; chia sẻ cảm nhận.","hs":"- HS biểu diễn nhóm; lắng nghe dặn dò."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 2) GV dùng đàn phím điện tử hoặc phần mềm đàn phím lấy cao độ chuẩn cho “Bài số 3 (nhịp 3/4)”: nghe mẫu từng nốt, nghe cả câu ở tốc độ chậm rồi tăng dần; HS chủ động xin nghe lại đúng quãng mình còn đọc chênh thay vì đọc lại cả bài.\n- (Miền 5: Giải quyết vấn đề — Cơ bản, bậc 2) HS luyện “Bài số 3 (nhịp 3/4)” bằng phần mềm đọc nhạc có chấm ngay: máy phát nốt, HS đọc lại, máy báo đúng hay còn cao hơn, thấp hơn; HS xem kết quả để tự chọn quãng cần luyện thêm và đặt mục tiêu cho lần sau.\n⚠ (Miền 4: An toàn) Chỉ mở phần mềm đàn phím và phần mềm đọc nhạc GV đã chỉ định, không mở trang khác trong giờ thực hành; nếu dùng tai nghe thì để âm lượng vừa và không quá 20 phút liên tục; máy chỉ báo được đúng sai về cao độ, còn đọc có mềm mại hay không thì phải nghe bằng tai mình và nghe GV góp ý.","hs":"- HS đọc đúng cao độ “Bài số 3 (nhịp 3/4)” nhờ nghe mẫu từ đàn phím.\n- HS tự xác định quãng mình còn đọc chênh và luyện lại đúng quãng đó."}]},
{"lop":5,"mon":"Âm nhạc","tuan":21,"tiet":21,"bai":"Chủ đề 5: Thiên nhiên tươi đẹp — Thường thức âm nhạc: Nhạc sĩ Bùi Đình Thảo; Ôn tập bài hát Em đi giữa biển vàng","yccd":"1. Năng lực âm nhạc (đặc thù)\n- Biết vài nét về cuộc đời, sự nghiệp nhạc sĩ Bùi Đình Thảo và một số ca khúc thiếu nhi của ông.\n- Hát thuộc, thể hiện đúng sắc thái bài Em đi giữa biển vàng.\n2. Năng lực chung\n- Tự chủ và tự học: Chủ động tìm hiểu, ghi nhớ thông tin nhạc sĩ.\n- Giao tiếp và hợp tác: Trao đổi, chia sẻ trong nhóm.\n- Giải quyết vấn đề và sáng tạo: Liên hệ tác phẩm với hình ảnh thiên nhiên.\n3. Phẩm chất\n- Trân trọng, biết ơn các nhạc sĩ sáng tác cho thiếu nhi.\n- Chăm chỉ, kiên trì học tập.\n4. Tích hợp\n- Năng lực số 1.1 CB2 (Duyệt, tìm kiếm và lọc dữ liệu, thông tin, nội dung số): HS nêu được đặc điểm nổi bật của “Nhạc sĩ Bùi Đình Thảo” nhờ quan sát tư liệu số và nghe bản thu.","dodung":"- GV: Máy tính, ti vi/máy chiếu, loa; bài giảng điện tử có hình ảnh, thông tin nhạc sĩ Bùi Đình Thảo, trích đoạn ca khúc; đàn phím điện tử.\n- HS: SGK Âm nhạc 5 (Kết nối tri thức với cuộc sống), vở ghi.","hoatdong":[{"ten":"A. KHỞI ĐỘNG (5 phút)","gv":"Mục tiêu: Tạo tâm thế vui vẻ, kết nối vào bài học.\n- GV cho lớp hát lại Em đi giữa biển vàng để khởi động.","hs":"- HS hát khởi động."},{"ten":"B. KHÁM PHÁ – HÌNH THÀNH KIẾN THỨC (15 phút)","gv":"Mục tiêu: HS hình thành kiến thức, kĩ năng trọng tâm của tiết.\n- GV giới thiệu vài nét về nhạc sĩ Bùi Đình Thảo và các ca khúc thiếu nhi tiêu biểu; cho HS nghe trích đoạn.\n- GV liên hệ bài Em đi giữa biển vàng với phong cách sáng tác của nhạc sĩ.","hs":"- HS lắng nghe, ghi nhớ vài nét về nhạc sĩ."},{"ten":"C. LUYỆN TẬP – THỰC HÀNH (10 phút)","gv":"Mục tiêu: HS luyện tập, củng cố kĩ năng vừa học.\n- HS nghe nhận biết trích đoạn ca khúc của nhạc sĩ; ôn bài hát theo nhóm.\n- GV sửa sai bài hát.","hs":"- HS thực hành nhận biết; luyện hát theo nhóm."},{"ten":"D. VẬN DỤNG (5 phút)","gv":"Mục tiêu: HS vận dụng, sáng tạo và liên hệ thực tế.\n- HS kể tên một bài hát thiếu nhi em thích và nói vì sao.","hs":"- HS chia sẻ; lắng nghe dặn dò."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 2) GV chiếu tư liệu số về “Nhạc sĩ Bùi Đình Thảo”: ảnh chân dung, mốc thời gian cuộc đời và bản thu những tác phẩm tiêu biểu lấy từ trang chính thống; HS nghe hai bài của cùng nhạc sĩ rồi nói bài nào em thích hơn và vì sao — nghe được tác phẩm thật khác hẳn chỉ đọc mấy dòng tiểu sử.\n- (Miền 5: Giải quyết vấn đề — Cơ bản, bậc 2) HS làm bài tập tương tác có chấm ngay về “Nhạc sĩ Bùi Đình Thảo”: nối tên bài hát với tên nhạc sĩ, sắp các mốc thời gian cho đúng thứ tự, nghe đoạn nhạc và chọn tên bài; sai câu nào HS mở lại đúng phần tư liệu của câu đó.\n⚠ (Miền 4: An toàn) Tư liệu về “Nhạc sĩ Bùi Đình Thảo” phải lấy từ trang của nhà xuất bản, nhà hát, bảo tàng hoặc kênh chính thức của nghệ sĩ và tải sẵn về máy trước giờ lên lớp để không lẫn quảng cáo; khi kể lại cho người khác phải nói rõ mình đã xem ở đâu, không nhận tư liệu của người khác là của mình; mở âm lượng vừa đủ nghe.","hs":"- HS nêu được đặc điểm nổi bật của “Nhạc sĩ Bùi Đình Thảo” nhờ quan sát tư liệu số và nghe bản thu.\n- HS làm bài tập tương tác, nhận ra âm sắc – nội dung đã học và tự sửa khi chọn sai."}]},
{"lop":5,"mon":"Âm nhạc","tuan":22,"tiet":22,"bai":"Chủ đề 5: Thiên nhiên tươi đẹp — Nhạc cụ; Vận dụng – Sáng tạo (tổng kết chủ đề 5)","yccd":"1. Năng lực âm nhạc (đặc thù)\n- Biết thể hiện mẫu tiết tấu/giai điệu đơn giản ở nhịp 3/4 trên nhạc cụ để đệm cho bài Em đi giữa biển vàng.\n- Biểu diễn tổng hợp hát – đệm nhạc cụ – vận động, thể hiện đúng sắc thái êm ả.\n2. Năng lực chung\n- Tự chủ và tự học: Chủ động luyện nhạc cụ.\n- Giao tiếp và hợp tác: Phối hợp trong nhóm hoà tấu, biểu diễn.\n- Giải quyết vấn đề và sáng tạo: Sáng tạo hình thức biểu diễn tổng hợp.\n3. Phẩm chất\n- Yêu thiên nhiên; tự tin, đoàn kết, chăm chỉ.","dodung":"- GV: Máy tính, ti vi/máy chiếu, loa; bài giảng điện tử; đàn phím điện tử; nhạc cụ gõ, nhạc cụ giai điệu nếu có.\n- HS: SGK Âm nhạc 5 (Kết nối tri thức với cuộc sống), vở ghi, nhạc cụ gõ tự tạo nếu có.","hoatdong":[{"ten":"A. KHỞI ĐỘNG (5 phút)","gv":"Mục tiêu: Tạo tâm thế vui vẻ, kết nối vào bài học.\n- GV gõ mẫu tiết tấu nhịp 3/4, HS gõ lặp lại để khởi động.","hs":"- HS tham gia trò chơi gõ tiết tấu."},{"ten":"B. KHÁM PHÁ – HÌNH THÀNH KIẾN THỨC (15 phút)","gv":"Mục tiêu: HS hình thành kiến thức, kĩ năng trọng tâm của tiết.\n- GV giới thiệu mẫu tiết tấu/giai điệu nhịp 3/4 đệm cho bài Em đi giữa biển vàng; làm mẫu.\n- Hướng dẫn HS thực hiện; kết hợp đệm với hát.","hs":"- HS quan sát, thực hành sử dụng nhạc cụ theo mẫu."},{"ten":"C. LUYỆN TẬP – THỰC HÀNH (10 phút)","gv":"Mục tiêu: HS luyện tập, củng cố kĩ năng vừa học.\n- HS luyện đệm nhạc cụ theo nhóm; ghép hát với đệm; GV sửa sai.","hs":"- HS luyện tập theo nhóm; tự nhận xét, sửa sai."},{"ten":"D. VẬN DỤNG (5 phút)","gv":"Mục tiêu: HS vận dụng, sáng tạo và liên hệ thực tế.\n- Các nhóm biểu diễn tổng hợp khép lại chủ đề 5; cả lớp nhận xét, bình chọn.","hs":"- HS biểu diễn, nhận xét bạn; lắng nghe dặn dò."}]},
{"lop":5,"mon":"Âm nhạc","tuan":23,"tiet":23,"bai":"Chủ đề 6: Ước mơ tuổi thơ — Học hát: Tuổi hồng ơi","yccd":"1. Năng lực âm nhạc (đặc thù)\n- Hát đúng cao độ, trường độ, lời ca bài Tuổi hồng ơi; thể hiện tính chất hồn nhiên, trong sáng, mơ mộng.\n- Biết hát rõ lời, lấy hơi đúng chỗ; hát kết hợp gõ đệm theo phách.\n2. Năng lực chung\n- Tự chủ và tự học: Chủ động luyện tập, tự điều chỉnh.\n- Giao tiếp và hợp tác: Phối hợp trong nhóm; lắng nghe, chia sẻ.\n- Giải quyết vấn đề và sáng tạo: Nghĩ động tác, cách gõ đệm phù hợp.\n3. Phẩm chất\n- Yêu tuổi thơ, có ước mơ đẹp; yêu bạn bè, mái trường.\n- Chăm chỉ, tích cực tham gia ca hát.\n4. Tích hợp\n- Năng lực số 1.1 CB2 (Duyệt, tìm kiếm và lọc dữ liệu, thông tin, nội dung số): HS nghe bản thu mẫu, hát đúng cao độ và biết xin mở lại đúng câu mình còn sai.","dodung":"- GV: Máy tính, ti vi/máy chiếu, loa; bài giảng điện tử có file hát mẫu, hình ảnh minh hoạ; đàn phím điện tử; nhạc cụ gõ.\n- HS: SGK Âm nhạc 5 (Kết nối tri thức với cuộc sống), vở ghi, nhạc cụ gõ.","hoatdong":[{"ten":"A. KHỞI ĐỘNG (5 phút)","gv":"Mục tiêu: Tạo tâm thế vui vẻ, kết nối vào bài học.\n- GV hỏi HS về một ước mơ tuổi thơ và dẫn vào bài Tuổi hồng ơi.","hs":"- HS chia sẻ ước mơ; ghi tên bài."},{"ten":"B. KHÁM PHÁ – HÌNH THÀNH KIẾN THỨC (15 phút)","gv":"Mục tiêu: HS hình thành kiến thức, kĩ năng trọng tâm của tiết.\n- GV hát mẫu bài Tuổi hồng ơi; hỏi cảm nhận.\n- Hướng dẫn đọc lời ca theo tiết tấu; dạy hát nối tiếp từng câu; nhắc lấy hơi, hát rõ lời.","hs":"- HS lắng nghe, quan sát, thực hành theo hướng dẫn."},{"ten":"C. LUYỆN TẬP – THỰC HÀNH (10 phút)","gv":"Mục tiêu: HS luyện tập, củng cố kĩ năng vừa học.\n- Cả lớp hát cả bài kết hợp gõ đệm theo phách; luyện theo tổ, nhóm, cá nhân.\n- GV sửa sai về cao độ, tiết tấu, phát âm.","hs":"- HS luyện tập theo tổ, nhóm, cá nhân; tự nhận xét, sửa sai."},{"ten":"D. VẬN DỤNG (5 phút)","gv":"Mục tiêu: HS vận dụng, sáng tạo và liên hệ thực tế.\n- HS hát bài cho bạn bè, người thân nghe; vẽ/nói về ước mơ tuổi thơ của mình.","hs":"- HS chia sẻ, biểu diễn; lắng nghe dặn dò."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 2) GV mở bản thu mẫu bài “Tuổi hồng ơi” từ học liệu điện tử của bộ sách, chỉ cho HS dòng ghi tên tác giả in kèm bản nhạc trong sách; HS nghe trọn bài một lần để nắm giai điệu và chỗ ngân, sau đó nghe từng câu và hát theo, chủ động xin GV mở lại đúng câu mình còn hát chênh.\n- (Miền 3: Sáng tạo nội dung số — Cơ bản, bậc 2) Tập xong, mỗi tổ tự thu âm phần trình bày bài “Tuổi hồng ơi” bằng điện thoại hoặc máy tính của lớp, nghe lại rồi chỉ ra chỗ vào chưa đều, chỗ hát chưa rõ lời để sửa và thu lần thứ hai.\n⚠ (Miền 4: An toàn) Chỉ lấy bản thu từ học liệu của bộ sách hoặc kênh chính thức của nhà xuất bản, không tải nhạc từ trang lạ và không chép nhạc của người khác rồi nhận là của mình; khi giới thiệu bài “Tuổi hồng ơi” phải nêu tên tác giả; bản thu giọng hát của tổ chỉ dùng trong giờ học, muốn gửi cho ai phải hỏi ý kiến cả tổ và GV.","hs":"- HS nghe bản thu mẫu, hát đúng cao độ và biết xin mở lại đúng câu mình còn sai.\n- HS thu âm, nghe lại phần trình bày bài “Tuổi hồng ơi” của tổ và nêu được chỗ đã sửa ở lần thu thứ hai."}]},
{"lop":5,"mon":"Âm nhạc","tuan":24,"tiet":24,"bai":"Chủ đề 6: Ước mơ tuổi thơ — Nghe nhạc: Ngôi sao sáng; Ôn tập bài hát Tuổi hồng ơi","yccd":"1. Năng lực âm nhạc (đặc thù)\n- Lắng nghe, cảm nhận được tính chất, sắc thái bài Ngôi sao sáng; biết vận động theo nhạc.\n- Hát thuộc, biểu diễn tự tin bài Tuổi hồng ơi.\n2. Năng lực chung\n- Tự chủ và tự học: Chủ động lắng nghe, nêu cảm nhận.\n- Giao tiếp và hợp tác: Chia sẻ cảm nhận, biểu diễn nhóm.\n- Giải quyết vấn đề và sáng tạo: Sáng tạo động tác vận động theo nhạc.\n3. Phẩm chất\n- Có ước mơ, hoài bão; yêu cuộc sống, lạc quan.\n- Chăm chỉ, tự tin.\n4. Tích hợp\n- Năng lực số 1.1 CB2 (Duyệt, tìm kiếm và lọc dữ liệu, thông tin, nội dung số): HS nêu được nét đặc sắc của tác phẩm “Ngôi sao sáng” nhờ vừa nghe vừa quan sát dàn nhạc biểu diễn.","dodung":"- GV: Máy tính, ti vi/máy chiếu, loa; bài giảng điện tử có file bài nghe Ngôi sao sáng; đàn phím điện tử; nhạc cụ gõ.\n- HS: SGK Âm nhạc 5 (Kết nối tri thức với cuộc sống), vở ghi.","hoatdong":[{"ten":"A. KHỞI ĐỘNG (5 phút)","gv":"Mục tiêu: Tạo tâm thế vui vẻ, kết nối vào bài học.\n- GV cho lớp hát lại Tuổi hồng ơi để khởi động.","hs":"- HS hát khởi động."},{"ten":"B. KHÁM PHÁ – HÌNH THÀNH KIẾN THỨC (15 phút)","gv":"Mục tiêu: HS hình thành kiến thức, kĩ năng trọng tâm của tiết.\n- GV cho HS nghe bài Ngôi sao sáng, gợi ý chú ý nhịp điệu, sắc thái.\n- GV đặt câu hỏi về cảm nhận; giới thiệu ngắn nội dung bài nghe.","hs":"- HS lắng nghe, cảm nhận, trả lời câu hỏi."},{"ten":"C. LUYỆN TẬP – THỰC HÀNH (10 phút)","gv":"Mục tiêu: HS luyện tập, củng cố kĩ năng vừa học.\n- HS nghe lại bài và vận động theo nhịp; ôn biểu diễn Tuổi hồng ơi theo nhóm.\n- GV sửa sai, hướng dẫn vận động.","hs":"- HS vận động theo nhạc; luyện biểu diễn nhóm."},{"ten":"D. VẬN DỤNG (5 phút)","gv":"Mục tiêu: HS vận dụng, sáng tạo và liên hệ thực tế.\n- HS nói cảm nhận sau khi nghe; chia sẻ một ước mơ khi lớn lên.","hs":"- HS chia sẻ; lắng nghe dặn dò."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 2) GV mở bản ghi hình buổi biểu diễn tác phẩm “Ngôi sao sáng”; HS vừa nghe vừa quan sát để nhận ra nhạc cụ nào giữ giai điệu chính, đoạn nào nhạc mạnh lên, đoạn nào chậm lại và ai là người bắt nhịp cho cả dàn nhạc — những điều chỉ nghe bản thu tiếng thì không thấy được.\n- (Miền 6: Ứng dụng trí tuệ nhân tạo — Cơ bản, bậc 2) GV mở thêm một đoạn nhạc do máy tự sinh theo phong cách gần giống rồi cho HS nghe đối chiếu với bản do nghệ sĩ biểu diễn; HS nêu chỗ khác nhau về sắc thái to nhỏ, chỗ nhanh chậm và nhận ra máy ghép lại theo những bản nhạc nó đã học nên chưa có cảm xúc của người chơi. GV mở và điều khiển công cụ, HS nghe và nhận xét.\n⚠ (Miền 4: An toàn) Bản ghi hình “Ngôi sao sáng” phải lấy từ kênh chính thức của nhà hát, dàn nhạc hoặc nhà xuất bản và tải về trước để không lẫn quảng cáo; khi nói hoặc viết về tác phẩm phải ghi tên tác giả và tên người biểu diễn, không cắt nhạc của người khác đem dùng khi chưa được phép; nghe bằng loa ở mức vừa, không đeo tai nghe mở to lâu.","hs":"- HS nêu được nét đặc sắc của tác phẩm “Ngôi sao sáng” nhờ vừa nghe vừa quan sát dàn nhạc biểu diễn.\n- HS chỉ ra được điểm khác giữa đoạn nhạc do máy tạo và đoạn do nghệ sĩ trình bày."}]},
{"lop":5,"mon":"Âm nhạc","tuan":25,"tiet":25,"bai":"Chủ đề 6: Ước mơ tuổi thơ — Nhạc cụ; Ôn tập bài hát Tuổi hồng ơi","yccd":"1. Năng lực âm nhạc (đặc thù)\n- Biết thể hiện mẫu tiết tấu/giai điệu đơn giản trên nhạc cụ để đệm cho bài Tuổi hồng ơi.\n- Hát kết hợp đệm nhạc cụ, thể hiện đúng sắc thái hồn nhiên, trong sáng.\n2. Năng lực chung\n- Tự chủ và tự học: Chủ động luyện nhạc cụ, tự sửa sai.\n- Giao tiếp và hợp tác: Phối hợp trong nhóm hoà tấu.\n- Giải quyết vấn đề và sáng tạo: Sáng tạo cách phối hợp hát – đệm.\n3. Phẩm chất\n- Yêu thích nhạc cụ, kiên trì luyện tập.\n- Đoàn kết, trách nhiệm.","dodung":"- GV: Máy tính, ti vi/máy chiếu, loa; bài giảng điện tử; đàn phím điện tử; nhạc cụ gõ, nhạc cụ giai điệu nếu có.\n- HS: SGK Âm nhạc 5 (Kết nối tri thức với cuộc sống), vở ghi, nhạc cụ gõ tự tạo nếu có.","hoatdong":[{"ten":"A. KHỞI ĐỘNG (5 phút)","gv":"Mục tiêu: Tạo tâm thế vui vẻ, kết nối vào bài học.\n- GV gõ mẫu tiết tấu, HS gõ lặp lại để khởi động.","hs":"- HS tham gia trò chơi gõ tiết tấu."},{"ten":"B. KHÁM PHÁ – HÌNH THÀNH KIẾN THỨC (15 phút)","gv":"Mục tiêu: HS hình thành kiến thức, kĩ năng trọng tâm của tiết.\n- GV giới thiệu mẫu tiết tấu/giai điệu đệm cho bài Tuổi hồng ơi; làm mẫu.\n- Hướng dẫn HS thực hiện từng mẫu; kết hợp đệm với hát.","hs":"- HS quan sát, thực hành sử dụng nhạc cụ theo mẫu."},{"ten":"C. LUYỆN TẬP – THỰC HÀNH (10 phút)","gv":"Mục tiêu: HS luyện tập, củng cố kĩ năng vừa học.\n- HS luyện đệm nhạc cụ theo nhóm; ghép hát với đệm; GV sửa sai.","hs":"- HS luyện tập theo nhóm; tự nhận xét, sửa sai."},{"ten":"D. VẬN DỤNG (5 phút)","gv":"Mục tiêu: HS vận dụng, sáng tạo và liên hệ thực tế.\n- Các nhóm biểu diễn hát kết hợp đệm nhạc cụ; nhận xét lẫn nhau.","hs":"- HS biểu diễn nhóm; lắng nghe dặn dò."}]},
{"lop":5,"mon":"Âm nhạc","tuan":26,"tiet":26,"bai":"Chủ đề 6: Ước mơ tuổi thơ — Vận dụng – Sáng tạo (tổng kết chủ đề 6)","yccd":"1. Năng lực âm nhạc (đặc thù)\n- Biểu diễn tổng hợp bài Tuổi hồng ơi kết hợp đệm nhạc cụ và vận động; thể hiện đúng sắc thái.\n- Vận dụng cảm thụ bài nghe Ngôi sao sáng vào việc nêu cảm nhận âm nhạc.\n2. Năng lực chung\n- Tự chủ và tự học: Tự tin thể hiện, tự điều chỉnh.\n- Giao tiếp và hợp tác: Phối hợp biểu diễn nhóm nhịp nhàng.\n- Giải quyết vấn đề và sáng tạo: Sáng tạo hình thức biểu diễn tổng hợp.\n3. Phẩm chất\n- Yêu tuổi thơ, nuôi dưỡng ước mơ; tự tin, đoàn kết, chăm chỉ.","dodung":"- GV: Máy tính, ti vi/máy chiếu, loa; bài giảng điện tử; đàn phím điện tử; nhạc cụ gõ, nhạc cụ giai điệu nếu có.\n- HS: SGK Âm nhạc 5 (Kết nối tri thức với cuộc sống), vở ghi, nhạc cụ gõ tự tạo nếu có.","hoatdong":[{"ten":"A. KHỞI ĐỘNG (5 phút)","gv":"Mục tiêu: Tạo tâm thế vui vẻ, kết nối vào bài học.\n- GV cho lớp hát lại Tuổi hồng ơi và ôn mẫu gõ đệm.","hs":"- HS hát và gõ đệm ôn lại."},{"ten":"B. KHÁM PHÁ – HÌNH THÀNH KIẾN THỨC (15 phút)","gv":"Mục tiêu: HS hình thành kiến thức, kĩ năng trọng tâm của tiết.\n- GV hướng dẫn nhóm dàn dựng tiết mục tổng hợp: hát – đệm nhạc cụ – vận động; phân vai.\n- Gợi ý sáng tạo động tác thể hiện ước mơ tuổi thơ.","hs":"- HS thảo luận, phân vai, dàn dựng tiết mục."},{"ten":"C. LUYỆN TẬP – THỰC HÀNH (10 phút)","gv":"Mục tiêu: HS luyện tập, củng cố kĩ năng vừa học.\n- Các nhóm luyện tập tiết mục; GV góp ý, chỉnh sửa.","hs":"- HS luyện tập tiết mục theo nhóm; tự điều chỉnh."},{"ten":"D. VẬN DỤNG (5 phút)","gv":"Mục tiêu: HS vận dụng, sáng tạo và liên hệ thực tế.\n- Các nhóm biểu diễn khép lại chủ đề 6; cả lớp nhận xét, bình chọn.","hs":"- HS biểu diễn, nhận xét bạn; lắng nghe dặn dò."}]},
{"lop":5,"mon":"Âm nhạc","tuan":27,"tiet":27,"bai":"Ôn tập giữa học kì 2","yccd":"1. Năng lực âm nhạc (đặc thù)\n- Hát thuộc, đúng sắc thái các bài Em đi giữa biển vàng, Tuổi hồng ơi; đọc lại Bài đọc nhạc số 3.\n- Củng cố kiến thức nhịp 3/4; nhận biết nhạc sĩ Bùi Đình Thảo và các bài nghe đã học.\n2. Năng lực chung\n- Tự chủ và tự học: Tự ôn tập, hệ thống nội dung đã học.\n- Giao tiếp và hợp tác: Ôn luyện, biểu diễn theo nhóm.\n- Giải quyết vấn đề và sáng tạo: Vận dụng linh hoạt kiến thức.\n3. Phẩm chất\n- Chăm chỉ ôn tập; tự tin thể hiện.\n- Trách nhiệm, đoàn kết trong nhóm.","dodung":"- GV: Máy tính, ti vi/máy chiếu, loa; bài giảng điện tử tổng hợp chủ đề 5–6; đàn phím điện tử; nhạc cụ gõ.\n- HS: SGK Âm nhạc 5 (Kết nối tri thức với cuộc sống), vở ghi, nhạc cụ gõ.","hoatdong":[{"ten":"A. KHỞI ĐỘNG (5 phút)","gv":"Mục tiêu: Tạo tâm thế vui vẻ, kết nối vào bài học.\n- GV cho HS chơi trò chơi đoán tên bài hát/nhạc sĩ đã học qua đoạn nhạc ngắn.","hs":"- HS tham gia trò chơi, nhớ lại nội dung đã học."},{"ten":"B. KHÁM PHÁ – HÌNH THÀNH KIẾN THỨC (15 phút)","gv":"Mục tiêu: HS hình thành kiến thức, kĩ năng trọng tâm của tiết.\n- GV hệ thống lại kiến thức chủ đề 5–6: bài hát, đọc nhạc nhịp 3/4, nhạc sĩ, bài nghe.\n- GV cho HS ôn từng nội dung, chốt điểm dễ sai.","hs":"- HS ôn tập, hệ thống kiến thức theo hướng dẫn."},{"ten":"C. LUYỆN TẬP – THỰC HÀNH (10 phút)","gv":"Mục tiêu: HS luyện tập, củng cố kĩ năng vừa học.\n- HS luyện hát, đọc nhạc, gõ đệm theo nhóm; GV sửa sai.","hs":"- HS luyện tập theo nhóm; tự nhận xét, sửa sai."},{"ten":"D. VẬN DỤNG (5 phút)","gv":"Mục tiêu: HS vận dụng, sáng tạo và liên hệ thực tế.\n- Nhóm biểu diễn tổng hợp một nội dung tự chọn; cả lớp nhận xét.","hs":"- HS biểu diễn, nhận xét bạn; lắng nghe dặn dò."}]},
{"lop":5,"mon":"Âm nhạc","tuan":28,"tiet":28,"bai":"Chủ đề 7: Âm nhạc nước ngoài — Học hát: Đất nước tươi đẹp sao (Nhạc Ma-lai-xi-a)","yccd":"1. Năng lực âm nhạc (đặc thù)\n- Hát đúng cao độ, trường độ, lời ca bài Đất nước tươi đẹp sao; thể hiện tính chất vui tươi, rộn ràng.\n- Biết hát rõ lời, lấy hơi đúng chỗ; hát kết hợp gõ đệm theo phách.\n2. Năng lực chung\n- Tự chủ và tự học: Chủ động luyện tập, tự điều chỉnh.\n- Giao tiếp và hợp tác: Phối hợp trong nhóm; lắng nghe, chia sẻ.\n- Giải quyết vấn đề và sáng tạo: Nghĩ động tác, cách gõ đệm phù hợp.\n3. Phẩm chất\n- Yêu hoà bình, hữu nghị; trân trọng âm nhạc, văn hoá các nước.\n- Chăm chỉ, tích cực tham gia ca hát.\n4. Tích hợp\n- Năng lực số 1.1 CB2 (Duyệt, tìm kiếm và lọc dữ liệu, thông tin, nội dung số): HS nghe bản thu mẫu, hát đúng cao độ và biết xin mở lại đúng câu mình còn sai.","dodung":"- GV: Máy tính, ti vi/máy chiếu, loa; bài giảng điện tử có file hát mẫu, hình ảnh đất nước Ma-lai-xi-a; đàn phím điện tử; nhạc cụ gõ.\n- HS: SGK Âm nhạc 5 (Kết nối tri thức với cuộc sống), vở ghi, nhạc cụ gõ.","hoatdong":[{"ten":"A. KHỞI ĐỘNG (5 phút)","gv":"Mục tiêu: Tạo tâm thế vui vẻ, kết nối vào bài học.\n- GV cho HS xem hình ảnh đất nước Ma-lai-xi-a và hỏi hiểu biết; dẫn vào bài.","hs":"- HS quan sát, chia sẻ; ghi tên bài."},{"ten":"B. KHÁM PHÁ – HÌNH THÀNH KIẾN THỨC (15 phút)","gv":"Mục tiêu: HS hình thành kiến thức, kĩ năng trọng tâm của tiết.\n- GV giới thiệu ngắn về bài hát nước ngoài; hát mẫu bài Đất nước tươi đẹp sao; hỏi cảm nhận.\n- Hướng dẫn đọc lời ca theo tiết tấu; dạy hát nối tiếp từng câu.","hs":"- HS lắng nghe, quan sát, thực hành theo hướng dẫn."},{"ten":"C. LUYỆN TẬP – THỰC HÀNH (10 phút)","gv":"Mục tiêu: HS luyện tập, củng cố kĩ năng vừa học.\n- Cả lớp hát cả bài kết hợp gõ đệm theo phách; luyện theo tổ, nhóm, cá nhân.\n- GV sửa sai về cao độ, tiết tấu, phát âm.","hs":"- HS luyện tập theo tổ, nhóm, cá nhân; tự nhận xét, sửa sai."},{"ten":"D. VẬN DỤNG (5 phút)","gv":"Mục tiêu: HS vận dụng, sáng tạo và liên hệ thực tế.\n- HS hát bài cho người thân nghe; kể tên một quốc gia em muốn tìm hiểu về âm nhạc.","hs":"- HS chia sẻ, biểu diễn; lắng nghe dặn dò."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 2) GV mở bản thu mẫu bài “Đất nước tươi đẹp sao” từ học liệu điện tử của bộ sách, chỉ cho HS dòng ghi tác giả “Nhạc Ma-lai-xi-a”; HS nghe trọn bài một lần để nắm giai điệu và chỗ ngân, sau đó nghe từng câu và hát theo, chủ động xin GV mở lại đúng câu mình còn hát chênh.\n- (Miền 3: Sáng tạo nội dung số — Cơ bản, bậc 2) Tập xong, mỗi tổ tự thu âm phần trình bày bài “Đất nước tươi đẹp sao” bằng điện thoại hoặc máy tính của lớp, nghe lại rồi chỉ ra chỗ vào chưa đều, chỗ hát chưa rõ lời để sửa và thu lần thứ hai.\n⚠ (Miền 4: An toàn) Chỉ lấy bản thu từ học liệu của bộ sách hoặc kênh chính thức của nhà xuất bản, không tải nhạc từ trang lạ và không chép nhạc của người khác rồi nhận là của mình; khi giới thiệu bài “Đất nước tươi đẹp sao” phải nêu tên tác giả; bản thu giọng hát của tổ chỉ dùng trong giờ học, muốn gửi cho ai phải hỏi ý kiến cả tổ và GV.","hs":"- HS nghe bản thu mẫu, hát đúng cao độ và biết xin mở lại đúng câu mình còn sai.\n- HS thu âm, nghe lại phần trình bày bài “Đất nước tươi đẹp sao” của tổ và nêu được chỗ đã sửa ở lần thu thứ hai."}]},
{"lop":5,"mon":"Âm nhạc","tuan":29,"tiet":29,"bai":"Chủ đề 7: Âm nhạc nước ngoài — Nghe nhạc: Vũ điệu Tây Ban Nha; Ôn tập bài hát Đất nước tươi đẹp sao","yccd":"1. Năng lực âm nhạc (đặc thù)\n- Lắng nghe, cảm nhận được tính chất sôi động, đặc trưng của Vũ điệu Tây Ban Nha; biết vận động theo nhạc.\n- Hát thuộc, biểu diễn tự tin bài Đất nước tươi đẹp sao.\n2. Năng lực chung\n- Tự chủ và tự học: Chủ động lắng nghe, nêu cảm nhận.\n- Giao tiếp và hợp tác: Chia sẻ cảm nhận, biểu diễn nhóm.\n- Giải quyết vấn đề và sáng tạo: Sáng tạo động tác vận động theo nhạc.\n3. Phẩm chất\n- Tôn trọng, yêu thích âm nhạc, vũ điệu các nước; cởi mở, hữu nghị.\n- Chăm chỉ, tự tin.\n4. Tích hợp\n- Năng lực số 1.1 CB2 (Duyệt, tìm kiếm và lọc dữ liệu, thông tin, nội dung số): HS nêu được nét đặc sắc của tác phẩm “Vũ điệu Tây Ban Nha” nhờ vừa nghe vừa quan sát dàn nhạc biểu diễn.","dodung":"- GV: Máy tính, ti vi/máy chiếu, loa; bài giảng điện tử có file nghe Vũ điệu Tây Ban Nha, video vũ điệu; đàn phím điện tử; nhạc cụ gõ.\n- HS: SGK Âm nhạc 5 (Kết nối tri thức với cuộc sống), vở ghi.","hoatdong":[{"ten":"A. KHỞI ĐỘNG (5 phút)","gv":"Mục tiêu: Tạo tâm thế vui vẻ, kết nối vào bài học.\n- GV cho lớp hát lại Đất nước tươi đẹp sao để khởi động.","hs":"- HS hát khởi động."},{"ten":"B. KHÁM PHÁ – HÌNH THÀNH KIẾN THỨC (15 phút)","gv":"Mục tiêu: HS hình thành kiến thức, kĩ năng trọng tâm của tiết.\n- GV cho HS nghe Vũ điệu Tây Ban Nha, gợi ý chú ý tiết tấu sôi động, sắc thái.\n- GV giới thiệu ngắn về vũ điệu, nhạc cụ đặc trưng; đặt câu hỏi cảm nhận.","hs":"- HS lắng nghe, cảm nhận, trả lời câu hỏi."},{"ten":"C. LUYỆN TẬP – THỰC HÀNH (10 phút)","gv":"Mục tiêu: HS luyện tập, củng cố kĩ năng vừa học.\n- HS nghe lại bản nhạc và vỗ tay/vận động theo tiết tấu; ôn biểu diễn bài hát theo nhóm.\n- GV sửa sai, hướng dẫn vận động.","hs":"- HS vận động theo nhạc; luyện biểu diễn nhóm."},{"ten":"D. VẬN DỤNG (5 phút)","gv":"Mục tiêu: HS vận dụng, sáng tạo và liên hệ thực tế.\n- HS nói cảm nhận về vũ điệu; thử một động tác nhún nhảy theo tiết tấu.","hs":"- HS chia sẻ, vận động; lắng nghe dặn dò."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 2) GV mở bản ghi hình buổi biểu diễn tác phẩm “Vũ điệu Tây Ban Nha”; HS vừa nghe vừa quan sát để nhận ra nhạc cụ nào giữ giai điệu chính, đoạn nào nhạc mạnh lên, đoạn nào chậm lại và ai là người bắt nhịp cho cả dàn nhạc — những điều chỉ nghe bản thu tiếng thì không thấy được.\n- (Miền 6: Ứng dụng trí tuệ nhân tạo — Cơ bản, bậc 2) GV mở thêm một đoạn nhạc do máy tự sinh theo phong cách gần giống rồi cho HS nghe đối chiếu với bản do nghệ sĩ biểu diễn; HS nêu chỗ khác nhau về sắc thái to nhỏ, chỗ nhanh chậm và nhận ra máy ghép lại theo những bản nhạc nó đã học nên chưa có cảm xúc của người chơi. GV mở và điều khiển công cụ, HS nghe và nhận xét.\n⚠ (Miền 4: An toàn) Bản ghi hình “Vũ điệu Tây Ban Nha” phải lấy từ kênh chính thức của nhà hát, dàn nhạc hoặc nhà xuất bản và tải về trước để không lẫn quảng cáo; khi nói hoặc viết về tác phẩm phải ghi tên tác giả và tên người biểu diễn, không cắt nhạc của người khác đem dùng khi chưa được phép; nghe bằng loa ở mức vừa, không đeo tai nghe mở to lâu.","hs":"- HS nêu được nét đặc sắc của tác phẩm “Vũ điệu Tây Ban Nha” nhờ vừa nghe vừa quan sát dàn nhạc biểu diễn.\n- HS chỉ ra được điểm khác giữa đoạn nhạc do máy tạo và đoạn do nghệ sĩ trình bày."}]},
{"lop":5,"mon":"Âm nhạc","tuan":30,"tiet":30,"bai":"Chủ đề 7: Âm nhạc nước ngoài — Ôn tập lí thuyết âm nhạc; Nhạc cụ gõ; Ôn tập bài hát Đất nước tươi đẹp sao","yccd":"1. Năng lực âm nhạc (đặc thù)\n- Củng cố kiến thức lí thuyết đã học (trọng âm, phách, vạch nhịp, ô nhịp, nhịp 2/4, 3/4); vận dụng vào gõ đệm.\n- Biết thể hiện mẫu tiết tấu trên nhạc cụ gõ để đệm cho bài Đất nước tươi đẹp sao.\n2. Năng lực chung\n- Tự chủ và tự học: Chủ động ôn tập, tự sửa sai.\n- Giao tiếp và hợp tác: Phối hợp trong nhóm hoà tấu.\n- Giải quyết vấn đề và sáng tạo: Sáng tạo mẫu gõ đệm phù hợp.\n3. Phẩm chất\n- Chăm chỉ, kiên trì; đoàn kết, trách nhiệm.\n4. Tích hợp\n- Năng lực số 1.1 CB2 (Duyệt, tìm kiếm và lọc dữ liệu, thông tin, nội dung số): HS đọc và ghi được kí hiệu về ôn tập các kí hiệu ghi nhạc đã học nhờ đối chiếu hình vẽ trên màn hình với âm thanh nghe được.","dodung":"- GV: Máy tính, ti vi/máy chiếu, loa; bài giảng điện tử ôn lí thuyết; đàn phím điện tử; nhạc cụ gõ.\n- HS: SGK Âm nhạc 5 (Kết nối tri thức với cuộc sống), vở ghi, nhạc cụ gõ.","hoatdong":[{"ten":"A. KHỞI ĐỘNG (5 phút)","gv":"Mục tiêu: Tạo tâm thế vui vẻ, kết nối vào bài học.\n- GV gõ mẫu tiết tấu nhịp 2/4 và 3/4, HS đoán nhịp để khởi động.","hs":"- HS nghe, đoán nhịp, gõ lặp."},{"ten":"B. KHÁM PHÁ – HÌNH THÀNH KIẾN THỨC (15 phút)","gv":"Mục tiêu: HS hình thành kiến thức, kĩ năng trọng tâm của tiết.\n- GV hệ thống lại lí thuyết: trọng âm, phách, vạch nhịp, ô nhịp, nhịp 2/4, 3/4.\n- GV giới thiệu mẫu tiết tấu gõ đệm cho bài Đất nước tươi đẹp sao; làm mẫu.","hs":"- HS ôn lí thuyết; quan sát, thực hành gõ mẫu tiết tấu."},{"ten":"C. LUYỆN TẬP – THỰC HÀNH (10 phút)","gv":"Mục tiêu: HS luyện tập, củng cố kĩ năng vừa học.\n- HS luyện gõ đệm theo nhóm; ghép hát với gõ đệm; GV sửa sai.","hs":"- HS luyện tập theo nhóm; tự nhận xét, sửa sai."},{"ten":"D. VẬN DỤNG (5 phút)","gv":"Mục tiêu: HS vận dụng, sáng tạo và liên hệ thực tế.\n- Các nhóm biểu diễn hát kết hợp gõ đệm; nhận xét lẫn nhau.","hs":"- HS biểu diễn nhóm; lắng nghe dặn dò."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 2) GV dùng học liệu số về ôn tập các kí hiệu ghi nhạc đã học: khuông nhạc hiện trên màn hình, GV kéo nốt lên xuống thì máy phát ngay âm thanh tương ứng, bấm vào hình nốt thì nghe được đúng độ dài của nốt đó — HS thấy được mối liên hệ giữa kí hiệu ghi trên giấy và âm thanh thật, điều mà nhìn hình in tĩnh trong sách không cho thấy.\n- (Miền 5: Giải quyết vấn đề — Cơ bản, bậc 2) HS làm bộ bài tập tương tác có chấm ngay về ôn tập các kí hiệu ghi nhạc đã học: đặt nốt vào đúng vị trí trên khuông, chọn hình nốt đúng với tiếng gõ vừa nghe, chia ô nhịp cho đủ phách; sai ở đâu máy báo ngay, HS xem lại phần lí thuyết đúng chỗ đó rồi làm lại.\n⚠ (Miền 4: An toàn) Chỉ mở học liệu và phần mềm GV đã chuẩn bị sẵn trên máy của lớp, không mở trang khác trong giờ; làm hết bài rồi mới xem đáp án, xem để hiểu chứ không chép; ngồi cách màn hình vừa tầm mắt và nghỉ mắt sau mỗi 20 phút nhìn màn hình.","hs":"- HS đọc và ghi được kí hiệu về ôn tập các kí hiệu ghi nhạc đã học nhờ đối chiếu hình vẽ trên màn hình với âm thanh nghe được.\n- HS làm bài tập tương tác, tự biết mình còn sai phần nào và ôn lại đúng phần đó."}]},
{"lop":5,"mon":"Âm nhạc","tuan":31,"tiet":31,"bai":"Chủ đề 7: Âm nhạc nước ngoài — Vận dụng – Sáng tạo (tổng kết chủ đề 7)","yccd":"1. Năng lực âm nhạc (đặc thù)\n- Biểu diễn tổng hợp bài Đất nước tươi đẹp sao kết hợp gõ đệm và vận động.\n- Vận dụng cảm thụ Vũ điệu Tây Ban Nha vào việc nêu cảm nhận âm nhạc nước ngoài.\n2. Năng lực chung\n- Tự chủ và tự học: Tự tin thể hiện, tự điều chỉnh.\n- Giao tiếp và hợp tác: Phối hợp biểu diễn nhóm nhịp nhàng.\n- Giải quyết vấn đề và sáng tạo: Sáng tạo hình thức biểu diễn tổng hợp.\n3. Phẩm chất\n- Yêu hoà bình, hữu nghị; tự tin, đoàn kết, chăm chỉ.","dodung":"- GV: Máy tính, ti vi/máy chiếu, loa; bài giảng điện tử; đàn phím điện tử; nhạc cụ gõ, nhạc cụ giai điệu nếu có.\n- HS: SGK Âm nhạc 5 (Kết nối tri thức với cuộc sống), vở ghi, nhạc cụ gõ tự tạo nếu có.","hoatdong":[{"ten":"A. KHỞI ĐỘNG (5 phút)","gv":"Mục tiêu: Tạo tâm thế vui vẻ, kết nối vào bài học.\n- GV cho lớp hát lại Đất nước tươi đẹp sao và ôn mẫu gõ đệm.","hs":"- HS hát và gõ đệm ôn lại."},{"ten":"B. KHÁM PHÁ – HÌNH THÀNH KIẾN THỨC (15 phút)","gv":"Mục tiêu: HS hình thành kiến thức, kĩ năng trọng tâm của tiết.\n- GV hướng dẫn nhóm dàn dựng tiết mục tổng hợp: hát – gõ đệm – vận động (kết hợp động tác vũ điệu đã xem); phân vai.\n- Gợi ý sáng tạo động tác mang màu sắc âm nhạc nước ngoài.","hs":"- HS thảo luận, phân vai, dàn dựng tiết mục."},{"ten":"C. LUYỆN TẬP – THỰC HÀNH (10 phút)","gv":"Mục tiêu: HS luyện tập, củng cố kĩ năng vừa học.\n- Các nhóm luyện tập tiết mục; GV góp ý, chỉnh sửa.","hs":"- HS luyện tập tiết mục theo nhóm; tự điều chỉnh."},{"ten":"D. VẬN DỤNG (5 phút)","gv":"Mục tiêu: HS vận dụng, sáng tạo và liên hệ thực tế.\n- Các nhóm biểu diễn khép lại chủ đề 7; cả lớp nhận xét, bình chọn.","hs":"- HS biểu diễn, nhận xét bạn; lắng nghe dặn dò."}]},
{"lop":5,"mon":"Âm nhạc","tuan":32,"tiet":32,"bai":"Chủ đề 8: Khúc ca hè về — Học hát: Khúc ca hè về","yccd":"1. Năng lực âm nhạc (đặc thù)\n- Hát đúng cao độ, trường độ, lời ca bài Khúc ca hè về; thể hiện tính chất rộn ràng, náo nức của ngày hè.\n- Biết hát rõ lời, lấy hơi đúng chỗ; hát kết hợp gõ đệm theo phách.\n2. Năng lực chung\n- Tự chủ và tự học: Chủ động luyện tập, tự điều chỉnh.\n- Giao tiếp và hợp tác: Phối hợp trong nhóm; lắng nghe, chia sẻ.\n- Giải quyết vấn đề và sáng tạo: Nghĩ động tác, cách gõ đệm phù hợp.\n3. Phẩm chất\n- Yêu thiên nhiên, yêu mùa hè; háo hức với kì nghỉ, trân trọng thời gian bên gia đình.\n- Chăm chỉ, tích cực tham gia ca hát.\n4. Tích hợp\n- Năng lực số 1.1 CB2 (Duyệt, tìm kiếm và lọc dữ liệu, thông tin, nội dung số): HS nghe bản thu mẫu, hát đúng cao độ và biết xin mở lại đúng câu mình còn sai.","dodung":"- GV: Máy tính, ti vi/máy chiếu, loa; bài giảng điện tử có file hát mẫu, hình ảnh mùa hè; đàn phím điện tử; nhạc cụ gõ.\n- HS: SGK Âm nhạc 5 (Kết nối tri thức với cuộc sống), vở ghi, nhạc cụ gõ.","hoatdong":[{"ten":"A. KHỞI ĐỘNG (5 phút)","gv":"Mục tiêu: Tạo tâm thế vui vẻ, kết nối vào bài học.\n- GV cho HS nghe tiếng ve, xem hình ảnh mùa hè và hỏi cảm nhận; dẫn vào bài.","hs":"- HS quan sát, chia sẻ; ghi tên bài."},{"ten":"B. KHÁM PHÁ – HÌNH THÀNH KIẾN THỨC (15 phút)","gv":"Mục tiêu: HS hình thành kiến thức, kĩ năng trọng tâm của tiết.\n- GV hát mẫu bài Khúc ca hè về; hỏi cảm nhận.\n- Hướng dẫn đọc lời ca theo tiết tấu; dạy hát nối tiếp từng câu; nhắc lấy hơi, hát rõ lời.","hs":"- HS lắng nghe, quan sát, thực hành theo hướng dẫn."},{"ten":"C. LUYỆN TẬP – THỰC HÀNH (10 phút)","gv":"Mục tiêu: HS luyện tập, củng cố kĩ năng vừa học.\n- Cả lớp hát cả bài kết hợp gõ đệm theo phách; luyện theo tổ, nhóm, cá nhân.\n- GV sửa sai về cao độ, tiết tấu, phát âm.","hs":"- HS luyện tập theo tổ, nhóm, cá nhân; tự nhận xét, sửa sai."},{"ten":"D. VẬN DỤNG (5 phút)","gv":"Mục tiêu: HS vận dụng, sáng tạo và liên hệ thực tế.\n- HS hát bài cho người thân nghe; chia sẻ dự định cho kì nghỉ hè.","hs":"- HS chia sẻ, biểu diễn; lắng nghe dặn dò."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 2) GV mở bản thu mẫu bài “Khúc ca hè về” từ học liệu điện tử của bộ sách, chỉ cho HS dòng ghi tên tác giả in kèm bản nhạc trong sách; HS nghe trọn bài một lần để nắm giai điệu và chỗ ngân, sau đó nghe từng câu và hát theo, chủ động xin GV mở lại đúng câu mình còn hát chênh.\n- (Miền 3: Sáng tạo nội dung số — Cơ bản, bậc 2) Tập xong, mỗi tổ tự thu âm phần trình bày bài “Khúc ca hè về” bằng điện thoại hoặc máy tính của lớp, nghe lại rồi chỉ ra chỗ vào chưa đều, chỗ hát chưa rõ lời để sửa và thu lần thứ hai.\n⚠ (Miền 4: An toàn) Chỉ lấy bản thu từ học liệu của bộ sách hoặc kênh chính thức của nhà xuất bản, không tải nhạc từ trang lạ và không chép nhạc của người khác rồi nhận là của mình; khi giới thiệu bài “Khúc ca hè về” phải nêu tên tác giả; bản thu giọng hát của tổ chỉ dùng trong giờ học, muốn gửi cho ai phải hỏi ý kiến cả tổ và GV.","hs":"- HS nghe bản thu mẫu, hát đúng cao độ và biết xin mở lại đúng câu mình còn sai.\n- HS thu âm, nghe lại phần trình bày bài “Khúc ca hè về” của tổ và nêu được chỗ đã sửa ở lần thu thứ hai."}]},
{"lop":5,"mon":"Âm nhạc","tuan":33,"tiet":33,"bai":"Chủ đề 8: Khúc ca hè về — Nghe nhạc: Khúc ca bốn mùa; Nhạc cụ; Ôn tập bài hát Khúc ca hè về","yccd":"1. Năng lực âm nhạc (đặc thù)\n- Lắng nghe, cảm nhận được tính chất bài Khúc ca bốn mùa; biết vận động theo nhạc.\n- Biết thể hiện mẫu tiết tấu trên nhạc cụ để đệm cho bài Khúc ca hè về; hát kết hợp đệm.\n2. Năng lực chung\n- Tự chủ và tự học: Chủ động lắng nghe, luyện nhạc cụ, tự sửa sai.\n- Giao tiếp và hợp tác: Phối hợp trong nhóm hoà tấu, biểu diễn.\n- Giải quyết vấn đề và sáng tạo: Sáng tạo cách phối hợp hát – đệm – vận động.\n3. Phẩm chất\n- Yêu thiên nhiên bốn mùa; yêu thích âm nhạc.\n- Chăm chỉ, đoàn kết, trách nhiệm.\n4. Tích hợp\n- Năng lực số 1.1 CB2 (Duyệt, tìm kiếm và lọc dữ liệu, thông tin, nội dung số): HS nêu được nét đặc sắc của tác phẩm “Khúc ca bốn mùa” nhờ vừa nghe vừa quan sát dàn nhạc biểu diễn.","dodung":"- GV: Máy tính, ti vi/máy chiếu, loa; bài giảng điện tử có file nghe Khúc ca bốn mùa; đàn phím điện tử; nhạc cụ gõ, nhạc cụ giai điệu nếu có.\n- HS: SGK Âm nhạc 5 (Kết nối tri thức với cuộc sống), vở ghi, nhạc cụ gõ.","hoatdong":[{"ten":"A. KHỞI ĐỘNG (5 phút)","gv":"Mục tiêu: Tạo tâm thế vui vẻ, kết nối vào bài học.\n- GV cho lớp hát lại Khúc ca hè về để khởi động.","hs":"- HS hát khởi động."},{"ten":"B. KHÁM PHÁ – HÌNH THÀNH KIẾN THỨC (15 phút)","gv":"Mục tiêu: HS hình thành kiến thức, kĩ năng trọng tâm của tiết.\n- GV cho HS nghe bài Khúc ca bốn mùa, gợi ý chú ý sắc thái từng mùa.\n- GV giới thiệu mẫu tiết tấu đệm cho bài Khúc ca hè về; làm mẫu, hướng dẫn HS thực hiện.","hs":"- HS lắng nghe bài nghe; quan sát, thực hành gõ đệm theo mẫu."},{"ten":"C. LUYỆN TẬP – THỰC HÀNH (10 phút)","gv":"Mục tiêu: HS luyện tập, củng cố kĩ năng vừa học.\n- HS luyện đệm nhạc cụ theo nhóm; ghép hát với đệm; GV sửa sai.","hs":"- HS luyện tập theo nhóm; tự nhận xét, sửa sai."},{"ten":"D. VẬN DỤNG (5 phút)","gv":"Mục tiêu: HS vận dụng, sáng tạo và liên hệ thực tế.\n- HS nói cảm nhận về bốn mùa; các nhóm biểu diễn hát kết hợp đệm nhạc cụ.","hs":"- HS chia sẻ, biểu diễn nhóm; lắng nghe dặn dò."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 2) GV mở bản ghi hình buổi biểu diễn tác phẩm “Khúc ca bốn mùa”; HS vừa nghe vừa quan sát để nhận ra nhạc cụ nào giữ giai điệu chính, đoạn nào nhạc mạnh lên, đoạn nào chậm lại và ai là người bắt nhịp cho cả dàn nhạc — những điều chỉ nghe bản thu tiếng thì không thấy được.\n- (Miền 6: Ứng dụng trí tuệ nhân tạo — Cơ bản, bậc 2) GV mở thêm một đoạn nhạc do máy tự sinh theo phong cách gần giống rồi cho HS nghe đối chiếu với bản do nghệ sĩ biểu diễn; HS nêu chỗ khác nhau về sắc thái to nhỏ, chỗ nhanh chậm và nhận ra máy ghép lại theo những bản nhạc nó đã học nên chưa có cảm xúc của người chơi. GV mở và điều khiển công cụ, HS nghe và nhận xét.\n⚠ (Miền 4: An toàn) Bản ghi hình “Khúc ca bốn mùa” phải lấy từ kênh chính thức của nhà hát, dàn nhạc hoặc nhà xuất bản và tải về trước để không lẫn quảng cáo; khi nói hoặc viết về tác phẩm phải ghi tên tác giả và tên người biểu diễn, không cắt nhạc của người khác đem dùng khi chưa được phép; nghe bằng loa ở mức vừa, không đeo tai nghe mở to lâu.","hs":"- HS nêu được nét đặc sắc của tác phẩm “Khúc ca bốn mùa” nhờ vừa nghe vừa quan sát dàn nhạc biểu diễn.\n- HS chỉ ra được điểm khác giữa đoạn nhạc do máy tạo và đoạn do nghệ sĩ trình bày."}]},
{"lop":5,"mon":"Âm nhạc","tuan":34,"tiet":34,"bai":"Chủ đề 8: Khúc ca hè về — Vận dụng – Sáng tạo (tổng kết chủ đề 8)","yccd":"1. Năng lực âm nhạc (đặc thù)\n- Biểu diễn tổng hợp bài Khúc ca hè về kết hợp đệm nhạc cụ và vận động; thể hiện đúng sắc thái rộn ràng.\n- Vận dụng cảm thụ bài nghe Khúc ca bốn mùa vào việc nêu cảm nhận âm nhạc.\n2. Năng lực chung\n- Tự chủ và tự học: Tự tin thể hiện, tự điều chỉnh.\n- Giao tiếp và hợp tác: Phối hợp biểu diễn nhóm nhịp nhàng.\n- Giải quyết vấn đề và sáng tạo: Sáng tạo hình thức biểu diễn tổng hợp.\n3. Phẩm chất\n- Yêu mùa hè, yêu cuộc sống; tự tin, đoàn kết, chăm chỉ.","dodung":"- GV: Máy tính, ti vi/máy chiếu, loa; bài giảng điện tử; đàn phím điện tử; nhạc cụ gõ, nhạc cụ giai điệu nếu có.\n- HS: SGK Âm nhạc 5 (Kết nối tri thức với cuộc sống), vở ghi, nhạc cụ gõ tự tạo nếu có.","hoatdong":[{"ten":"A. KHỞI ĐỘNG (5 phút)","gv":"Mục tiêu: Tạo tâm thế vui vẻ, kết nối vào bài học.\n- GV cho lớp hát lại Khúc ca hè về và ôn mẫu gõ đệm.","hs":"- HS hát và gõ đệm ôn lại."},{"ten":"B. KHÁM PHÁ – HÌNH THÀNH KIẾN THỨC (15 phút)","gv":"Mục tiêu: HS hình thành kiến thức, kĩ năng trọng tâm của tiết.\n- GV hướng dẫn nhóm dàn dựng tiết mục tổng hợp: hát – đệm nhạc cụ – vận động; phân vai.\n- Gợi ý sáng tạo động tác mô phỏng không khí ngày hè.","hs":"- HS thảo luận, phân vai, dàn dựng tiết mục."},{"ten":"C. LUYỆN TẬP – THỰC HÀNH (10 phút)","gv":"Mục tiêu: HS luyện tập, củng cố kĩ năng vừa học.\n- Các nhóm luyện tập tiết mục; GV góp ý, chỉnh sửa.","hs":"- HS luyện tập tiết mục theo nhóm; tự điều chỉnh."},{"ten":"D. VẬN DỤNG (5 phút)","gv":"Mục tiêu: HS vận dụng, sáng tạo và liên hệ thực tế.\n- Các nhóm biểu diễn khép lại chủ đề 8; cả lớp nhận xét, bình chọn.","hs":"- HS biểu diễn, nhận xét bạn; lắng nghe dặn dò."}]},
{"lop":5,"mon":"Âm nhạc","tuan":35,"tiet":35,"bai":"Ôn tập và kiểm tra cuối học kì 2 (cuối năm)","yccd":"1. Năng lực âm nhạc (đặc thù)\n- Hát thuộc, biểu diễn tự tin các bài học kì 2 (Em đi giữa biển vàng, Tuổi hồng ơi, Đất nước tươi đẹp sao, Khúc ca hè về); đọc lại các bài đọc nhạc đã học.\n- Củng cố toàn bộ kiến thức, kĩ năng âm nhạc lớp 5; tự đánh giá được sự tiến bộ của bản thân.\n2. Năng lực chung\n- Tự chủ và tự học: Tự ôn tập, hệ thống kiến thức cả năm.\n- Giao tiếp và hợp tác: Biểu diễn, đánh giá lẫn nhau.\n- Giải quyết vấn đề và sáng tạo: Vận dụng linh hoạt kiến thức vào biểu diễn tổng kết.\n3. Phẩm chất\n- Chăm chỉ, tự tin, trung thực khi tự đánh giá.\n- Yêu âm nhạc; đoàn kết, trách nhiệm.\n4. Tích hợp\n- Năng lực số 3.2 CB2 (Tích hợp và tinh chỉnh nội dung số): HS tự quay, xem lại và nêu được điều tổ mình đã sửa được giữa hai lần trình bày.","dodung":"- GV: Máy tính, ti vi/máy chiếu, loa; bài giảng điện tử tổng hợp cả năm; đàn phím điện tử; nhạc cụ gõ; phiếu đánh giá.\n- HS: SGK Âm nhạc 5 (Kết nối tri thức với cuộc sống), vở ghi, nhạc cụ gõ.","hoatdong":[{"ten":"A. KHỞI ĐỘNG (5 phút)","gv":"Mục tiêu: Tạo tâm thế vui vẻ, kết nối vào bài học.\n- GV cho HS chơi trò chơi liên khúc: hát nối các bài đã học trong năm.","hs":"- HS tham gia trò chơi liên khúc, nhớ lại các bài đã học."},{"ten":"B. KHÁM PHÁ – HÌNH THÀNH KIẾN THỨC (15 phút)","gv":"Mục tiêu: HS hình thành kiến thức, kĩ năng trọng tâm của tiết.\n- GV hệ thống toàn bộ mạch nội dung cả năm: hát, đọc nhạc, lí thuyết, nhạc cụ, nghe nhạc, thường thức âm nhạc.\n- GV nêu tiêu chí đánh giá phần biểu diễn tổng kết.","hs":"- HS ôn tập, nắm tiêu chí đánh giá."},{"ten":"C. LUYỆN TẬP – THỰC HÀNH (10 phút)","gv":"Mục tiêu: HS luyện tập, củng cố kĩ năng vừa học.\n- HS biểu diễn theo nhóm/cá nhân nội dung tự chọn; GV đánh giá theo tiêu chí.","hs":"- HS biểu diễn; tự đánh giá và đánh giá bạn."},{"ten":"D. VẬN DỤNG (5 phút)","gv":"Mục tiêu: HS vận dụng, sáng tạo và liên hệ thực tế.\n- GV nhận xét chung cả năm, tuyên dương; HS nêu bài hát/hoạt động em yêu thích nhất và dự định giữ thói quen hát, nghe nhạc trong hè.","hs":"- HS chia sẻ; lắng nghe dặn dò, lời chúc nghỉ hè."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 3: Sáng tạo nội dung số — Cơ bản, bậc 2) Mỗi tổ tự quay lại phần biểu diễn cuối năm học của mình, xem lại và chọn bản quay ưng ý nhất; HS nói rõ đã sửa chỗ nào giữa lần quay đầu và lần quay sau.\n- (Miền 2: Giao tiếp và hợp tác trong môi trường số — Cơ bản, bậc 2) HS viết lời giới thiệu ngắn cho bản quay của tổ — có tên bài hát, tên tác giả, tên các bạn biểu diễn — rồi gửi vào nhóm lớp cho các bạn và gia đình xem; trước khi gửi phải hỏi ý kiến từng bạn có mặt trong đoạn phim.\n- (Miền 6: Ứng dụng trí tuệ nhân tạo — Cơ bản, bậc 2) GV mở cho HS nghe một đoạn nhạc do máy tự tạo bên cạnh một đoạn do nghệ sĩ trình bày; HS so sánh sắc thái to nhỏ, chỗ nhanh chậm, hơi thở và rút ra: máy ghép lại từ những gì đã học được nên đều đặn nhưng khó có cảm xúc như người chơi. GV mở và điều khiển công cụ, HS nghe và nhận xét.\n⚠ (Miền 4: An toàn) Đoạn phim có mặt bạn chỉ được gửi khi từng bạn trong đó đồng ý và chỉ gửi trong nhóm lớp, không đăng ra mạng xã hội; giới thiệu bài hát phải ghi tên tác giả, không nhận bài của người khác là của mình; góp ý cho bạn bằng lời lịch sự, viết trong nhóm cũng phải như nói trước mặt.","hs":"- HS tự quay, xem lại và nêu được điều tổ mình đã sửa được giữa hai lần trình bày.\n- HS giới thiệu sản phẩm của tổ đúng phép lịch sự, có ghi tên tác giả và xin phép bạn trước khi chia sẻ."}]}
];
